# Generated from tools/data/rulebooks/mania_pisania.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class ManiaPisania
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:main_0, GameRoomRules.translate("Typoholism"),
            GameRoomRules.translate("Typoholism is a game where you can practise your typing speed, accuracy and memory. You can play on your own, compete with friends or simply track your progress."),
            GameRoomRules.translate("There are several modes to choose from, ranging from leisurely story transcription to challenges where every second counts. This guide explains how to start a game, how each mode works and what to pay attention to while typing.")),
          rule_section(:main_1, GameRoomRules.translate("Objective"),
            GameRoomRules.translate("Your goal is to type as quickly as possible while making as few mistakes as you can. Depending on the mode, you'll transcribe a prepared text, type random words, remember increasingly long word sequences or race against the clock.\nYou can play alone or with up to seven other people. In multiplayer, players compete for the best score, with victory depending on both the average number of correctly typed words per minute and accuracy, measured by the number of mistakes made."),
            GameRoomRules.translate("The main mode is Free Typing, where everyone transcribes the same text. Speed matters, but mistakes reduce your final score, so a more accurate player can win even if they type a little more slowly."),
            GameRoomRules.translate("The other modes let you practise different skills. Random Words tests your typing skills, Memory Chain challenges you to remember words in order, and Survival puts your reactions to the test.")),
          rule_section(:main_2, GameRoomRules.translate("Setup"),
            GameRoomRules.translate("Start by creating a game table. You can set it up for solo practice or invite other players to join you."),
            GameRoomRules.translate("Your most important choice is the game mode. Each of the four modes offers a different kind of challenge and lets you tailor the game to your preferences."),
            GameRoomRules.translate("Free Typing involves transcribing a selected text. You can use the built-in stories, your own files or pasted text. You can also set a time limit or, when playing solo, dispense with the source text and write something of your own."),
            GameRoomRules.translate("Random Words challenges you to type words presented by the game one at a time. You can use a regular keyboard, Braille input or a mixed mode that changes the input method from word to word."),
            GameRoomRules.translate("Memory Chain tests how well you can remember a growing sequence of words. With each attempt, you must reproduce all the words presented so far in the correct order."),
            GameRoomRules.translate("Survival combines typing random words with a race against the clock. You choose a difficulty level that determines the starting pace."),
            GameRoomRules.translate("Once you've configured the table, you can begin practising or publish it so that others can join. Standard PowerGames features are available, including invitations, spectating, chat and game history."),
            GameRoomRules.translate("You'll find the detailed rules for each mode and its available settings in the Game modes and table options section.")),
          rule_section(:main_3, GameRoomRules.translate("How to play"),
            GameRoomRules.translate("At the start of each new round, focus automatically returns to the typing field. If you move to another part of the interface during play, return focus to that field to continue."),
            GameRoomRules.translate("The game reads out the words you need to type. Depending on the mode, it may also read entire sentences or ask you to recall words you heard earlier."),
            GameRoomRules.translate("Usually, you confirm a word by pressing Space after typing it. The exception is Survival, where a correctly completed word is confirmed automatically."),
            GameRoomRules.translate("Mistakes are handled differently depending on the mode. In Free Typing, you can correct the current word with Backspace until you confirm it with Space. In the other modes, the game checks each character as you type. If you press an incorrect key, it waits for the correct one instead of moving on."),
            GameRoomRules.translate("During play, you can have words read aloud (Ctrl+O) or spelled out (Ctrl+L), and use other shortcuts to repeat parts of the text. Check the shortcuts list to discover all the available commands."),
            GameRoomRules.translate("When transcribing texts, you don't have to match letter case or reproduce every decorative typographic character. The game accepts simpler keyboard equivalents for all types of quotation marks, spaces, dashes and ellipses.\nIf the text contains numbers, the game will tell you to enter them as digits."),
            GameRoomRules.translate("When you import your own text, you'll also be notified of any unsupported characters that need changing.")),
          rule_section(:main_4, GameRoomRules.translate("Ending a game"),
            GameRoomRules.translate("How a game ends depends on the selected mode."),
            GameRoomRules.translate("In Free Typing, a round ends when you finish transcribing the text, the set time limit expires, or you choose End Typing."),
            GameRoomRules.translate("In Random Words, Memory Chain and Survival, a round ends after five mistakes. You can also end it manually."),
            GameRoomRules.translate("In multiplayer, the results appear once everyone has finished. The player with the highest score wins. If two or more players have exactly the same score, it's a tie."),
            GameRoomRules.translate("In a match consisting of multiple rounds, the overall winner is determined by the number of rounds won."),
            GameRoomRules.translate("Typoholism rewards both typing proficiency and accuracy. That's why your final score isn't simply the number of words you typed."),
            GameRoomRules.translate("In Free Typing, one measure of performance is WPM, or correctly typed words per minute. The game counts the time spent typing them, but not the time spent listening before you press the first key of a word. You can therefore listen to the whole word first to make sure you know what to type."),
            GameRoomRules.translate("In Random Words, Memory Chain and Survival, the score is based on the number of correctly typed words."),
            GameRoomRules.translate("In every mode, the game also calculates an accuracy factor. This is the number of correct words divided by the total of correct words and mistakes."),
            GameRoomRules.translate("The base score is then multiplied by that accuracy factor twice."),
            GameRoomRules.translate("For example, if you type 20 words correctly and make 4 mistakes, your final score will be approximately 13.89 points."),
            GameRoomRules.translate("Someone who types 17 words without a single mistake will score 17 points and win.\nAs you can see, typing as fast as possible isn't always the best strategy. A slightly slower but more accurate approach can pay off.\nThe summary displays your final score and accuracy percentage.")),
          rule_section(:main_5, GameRoomRules.translate("Game modes and table options"),
            GameRoomRules.translate("Each Typoholism mode has slightly different rules. The differences involve not only the task itself, but also how mistakes are corrected, how words are confirmed and which settings are available.")),
          rule_section(:main_6, GameRoomRules.translate("Free Typing"),
            GameRoomRules.translate("In this mode, you transcribe a selected text word by word, either using regular typing or by simulating a Braille keyboard layout. In multiplayer, everyone receives the same text."),
            GameRoomRules.translate("At the beginning, the game reads the current sentence, followed by the first word you need to type."),
            GameRoomRules.translate("Type it exactly, including punctuation, and press Space to continue."),
            GameRoomRules.translate("Until you confirm a word, you can correct it with Backspace. Once you press Space, the game checks the word and moves on to the next one."),
            GameRoomRules.translate("If you make a mistake, you'll hear a distinctive sound and a message, but the game will continue.\nYou can choose from built-in texts in the table settings, import your own files or paste any text.\nOnce you select a text, its title and character count, including spaces, appear in the table description. They are also displayed in the table widget, allowing other players to estimate the length of the game before joining."),
            GameRoomRules.translate("To use your own material, choose Paste Text. Enter its title in the table settings, then press Tab to move to the text field."),
            GameRoomRules.translate("Imported files must use UTF-8 encoding. The maximum size of a file or pasted text is 1,000 kB. Since some characters take up more than one byte, this corresponds to slightly fewer than a million characters. Your texts are stored locally on your computer. However, if you use your own text in multiplayer, it is shared with the participants through the Elten server when the game starts.\nBy default, Free Typing continues until the entire text is finished. If you'd prefer a shorter game, you can set a time limit. When it expires, the round ends even if you're in the middle of a word.\nWhen playing solo, you can also choose to type without a source text. Instead of transcribing something prepared, you write your own text. Without a time limit, you can keep writing for as long as you like. To finish such a session, choose End Typing.\nWhen transcribing a built-in text on your own, the game saves your progress locally when you finish or leave. This lets you resume later rather than starting the same text again. If you want to repeat it from the beginning, reset its progress in Local Texts and Progress.")),
          rule_section(:main_7, GameRoomRules.translate("Random Words"),
            GameRoomRules.translate("In this mode, the game reads out randomly selected words one after another. Your task is to type each one correctly and confirm it with Space."),
            GameRoomRules.translate("Unlike Free Typing, each character is checked as soon as you enter it. If you press the wrong key, you make one mistake, but the cursor stays in place. You must enter the correct character to continue."),
            GameRoomRules.translate("Backspace doesn't work because incorrect characters aren't added to the correctly typed beginning of the word."),
            GameRoomRules.translate("Multiplayer games also have a five-second inactivity limit.\nIf you don't start typing or continue typing within that time, you receive a mistake. The timer also runs before you press the first key."),
            GameRoomRules.translate("You can use the appropriate shortcut to have the word read aloud or spelled out. The timer pauses while the screen reader is speaking, and once it finishes, you get a full five seconds again."),
            GameRoomRules.translate("There is no inactivity penalty when playing solo, so you can practise at your own pace.\nIn this mode's settings, you can choose a regular keyboard, Braille input or mixed mode."),
            GameRoomRules.translate("In mixed mode, the game randomly selects an input method for each word."),
            GameRoomRules.translate("You'll find more information about Braille input later in this guide.")),
          rule_section(:main_9, GameRoomRules.translate("Memory Chain"),
            GameRoomRules.translate("This mode is about remembering an increasingly long sequence of words."),
            GameRoomRules.translate("First, the game gives you one word to type. It then adds another, but reads aloud only the new word."),
            GameRoomRules.translate("Each time, you must reproduce the entire sequence from the beginning, separating the words with Space."),
            GameRoomRules.translate("For example, if you first hear \u201Ccat\u201D and then \u201Cgarden\u201D, you must type both words in the correct order. When a third word is added, you type all three."),
            GameRoomRules.translate("Each attempt gets harder as there are more words to remember."),
            GameRoomRules.translate("As in Random Words, an incorrect character adds one mistake but doesn't move the cursor, and Backspace isn't available. This mode also has the same inactivity penalty and supports Braille input."),
            GameRoomRules.translate("Mixed mode here is for incurable nerds, because you have to recall both the word and the way you were supposed to type it.")),
          rule_section(:main_10, GameRoomRules.translate("Survival mode"),
            GameRoomRules.translate("In Survival, you need to type each new word before the music stops playing."),
            GameRoomRules.translate("Each word has its own time limit, determined by the length of the recording."),
            GameRoomRules.translate("You can choose one of three difficulty levels in the table settings."),
            GameRoomRules.translate("- Easy - approximately 16 seconds at the start.\n- Medium - approximately 10.67 seconds at the start.\n- Hard - approximately 6.64 seconds at the start."),
            GameRoomRules.translate("After every correctly completed word, the music speeds up by 2.5 percent and its pitch rises."),
            GameRoomRules.translate("This means that the longer you play without mistakes, the less time you have to type each new word.\nIn this mode, you don't confirm words with Space. As soon as you type the last correct character, the game moves to the next word automatically."),
            GameRoomRules.translate("If you press the wrong key, you get a mistake but keep the correctly typed beginning of the word."),
            GameRoomRules.translate("If the music ends before you've finished a word, the game adds a mistake and starts a new word. In that case, the music doesn't speed up.\nRemember that reading words aloud, spelling them out and muting the music do not stop the countdown."),
            GameRoomRules.translate("There is no separate inactivity timer here, because the music itself sets the time limit for each word."),
            GameRoomRules.translate("You can also use a regular keyboard, Braille input or mixed mode here.")),
          rule_section(:main_11, GameRoomRules.translate("Braille input"),
            GameRoomRules.translate("Instead of entering characters with individual keys, you can use a layout that simulates a Braille keyboard."),
            GameRoomRules.translate("Braille dots correspond to the following keys."),
            GameRoomRules.translate("- Dots 1, 2 and 3 - F, D, S.\n- Dots 4, 5 and 6 - J, K, L.\n- Dot 7 - A.\n- Dot 8 - semicolon."),
            GameRoomRules.translate("To enter a Braille character, press the corresponding keys together, then release them.\nIn Typoholism Settings, you can choose different Braille tables for your language, or a local Liblouis table provided as a ctb, utb, tbl or uti file.")),
          rule_section(:main_12, GameRoomRules.translate("Typoholism Settings"),
            GameRoomRules.translate("Press Ctrl+P to open Typoholism Settings."),
            GameRoomRules.translate("Here you can configure Braille input, typing echo, error notifications and music volume."),
            GameRoomRules.translate("Typing echo controls what the game reads aloud as you type."),
            GameRoomRules.translate("You can follow Elten's settings, have characters read aloud, have words read aloud, hear both characters and words, or turn echo off entirely."),
            GameRoomRules.translate("These changes apply only to the typing field during the game.\nAnother setting controls how the game informs you about mistakes."),
            GameRoomRules.translate("Spoken and sound notifications are independent. You can enable both, choose just one or turn notifications off completely.\nThe final option is a music volume slider ranging from 0 to 100 percent.")),
          rule_section(:main_13, GameRoomRules.translate("Rounds and multiplayer matches"),
            GameRoomRules.translate("In Random Words, Memory Chain and Survival, you can choose a fixed number of rounds or play a match that continues until the host ends it."),
            GameRoomRules.translate("In each round, players earn scores according to the rules of the selected mode."),
            GameRoomRules.translate("In a multi-round match, the overall winner is the player who wins the most rounds."),
            GameRoomRules.translate("This allows for both a quick game and a longer tournament in which a single setback doesn't necessarily decide the final result.")),
          rule_section(:touch_0, GameRoomRules.translate("Touch typing"),
            GameRoomRules.translate("Touch typing means entering text without looking at the keyboard. With regular practice, you'll learn to find keys automatically, which can improve your typing speed, accuracy, and comfort. Touch typing is a valuable skill for people in many professions where typing speed directly affects productivity, such as programmers, journalists, and writers.")),
          rule_section(:touch_1, GameRoomRules.translate("Basic Principles"),
            GameRoomRules.translate("Place the fingers of your left hand on the A, S, D, and F keys, and those of your right hand on J, K, L, and the semicolon (;). Rest your thumbs on the spacebar."),
            GameRoomRules.translate("The F and J keys have small raised bumps that help you find the starting position for both hands without looking."),
            GameRoomRules.translate("This is your home position. From here, you can type other characters by moving your fingers to nearby keys. For example, to type z, move your left pinky down from a. To type q, move the same finger up. To type y, move your right index finger diagonally up and to the left from j.")),
          rule_section(:touch_2, GameRoomRules.translate("Five Golden Rules of Touch Typing"),
            GameRoomRules.translate("1. Use all your fingers. Each finger is assigned specific keys. Try to follow these assignments while learning."),
            GameRoomRules.translate("2. Return to the home position. After pressing a key, move your finger back to its starting position. For example, after typing r, return your left index finger to f."),
            GameRoomRules.translate("3. Use your thumb for the spacebar. For capital letters, use the Shift key on the opposite side of the keyboard. For example, use the right Shift key to type A, and the left Shift key to type K."),
            GameRoomRules.translate("4. Keep your hands relaxed. Make light, natural movements and keep your wrists as straight as comfortably possible."),
            GameRoomRules.translate("5. Don't rush. Focus on accuracy first. Speed will come with practice.")),
          rule_section(:touch_3, GameRoomRules.translate("How to Practice Effectively"),
            GameRoomRules.translate("Practice regularly. Start with short sessions lasting around 10-15 minutes."),
            GameRoomRules.translate("Focus on accuracy. Try to minimize typing errors before gradually increasing your speed."),
            GameRoomRules.translate("Repeat difficult combinations. If a particular key or word gives you trouble, spend some extra time practicing it."),
            GameRoomRules.translate("Track your progress. Compare your results across training sessions, but remember that speed isn't everything."),
            GameRoomRules.translate("Take breaks. If you start losing concentration or feel discomfort in your hands, stop practicing and rest.")),
          rule_section(:controls, GameRoomRules.translate("Keyboard shortcuts"),
            GameRoomRules.translate("- Ctrl+L: Spell the current word."),
            GameRoomRules.translate("- Ctrl+O: Read the current word."),
            GameRoomRules.translate("- Ctrl+;: Read the rest of the word (unavailable in Memory Chain)."),
            GameRoomRules.translate("- Ctrl+Shift+;: Read the rest of the sentence (Free Typing)."),
            GameRoomRules.translate("- Alt+S: Read progress."),
            GameRoomRules.translate("- Ctrl+P: Open typing settings."),
            GameRoomRules.translate("- Space: Confirm the word (except Survival)."),
            GameRoomRules.translate("- Backspace: Correct the current word (Free Typing)."),
            GameRoomRules.translate("- Ctrl+S: Save and close the table."),
            GameRoomRules.translate("- F1: Contextual help."),
            GameRoomRules.translate("- Ctrl+F1: Game help."),
            GameRoomRules.translate("- Escape: Leave the table."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:main_0, "Psanom\u00E1nie",
              "Psanom\u00E1nie je hra, ve kter\u00E9 si m\u016F\u017Ee\u0161 procvi\u010Dit rychlost psan\u00ED, p\u0159esnost a pam\u011B\u0165. M\u016F\u017Ee\u0161 hr\u00E1t samostatn\u011B, sout\u011B\u017Eit s p\u0159\u00E1teli nebo jen sledovat sv\u00E9 pokroky.",
              "Na v\u00FDb\u011Br m\u00E1\u0161 n\u011Bkolik re\u017Eim\u016F, od klidn\u00E9ho p\u0159episov\u00E1n\u00ED p\u0159\u00EDb\u011Bh\u016F a\u017E po v\u00FDzvy, ve kter\u00FDch z\u00E1le\u017E\u00ED na ka\u017Ed\u00E9 vte\u0159in\u011B. V t\u00E9to n\u00E1pov\u011Bd\u011B se dozv\u00ED\u0161, jak hru spustit, jak jednotliv\u00E9 re\u017Eimy funguj\u00ED a na co si p\u0159i psan\u00ED d\u00E1t pozor."),
            rule_section(:main_1, "C\u00EDl hry",
              "Tv\u00FDm \u00FAkolem je ps\u00E1t co nejrychleji a d\u011Blat co nejm\u00E9n\u011B chyb. Podle zvolen\u00E9ho re\u017Eimu bude\u0161 p\u0159episovat p\u0159ipraven\u00FD text, ps\u00E1t n\u00E1hodn\u00E1 slova, pamatovat si st\u00E1le del\u0161\u00ED \u0159et\u011Bzce slov nebo z\u00E1vodit s \u010Dasem.\nM\u016F\u017Ee\u0161 hr\u00E1t samostatn\u011B nebo a\u017E se sedmi dal\u0161\u00EDmi lidmi. Ve h\u0159e pro v\u00EDce hr\u00E1\u010D\u016F v\u0161ichni sout\u011B\u017E\u00ED o co nejlep\u0161\u00ED v\u00FDsledek. O v\u00EDt\u011Bzstv\u00ED rozhoduje pr\u016Fm\u011Brn\u00FD po\u010Det spr\u00E1vn\u011B napsan\u00FDch slov za minutu a p\u0159esnost, kterou ovliv\u0148uje po\u010Det chyb.",
              "Z\u00E1kladn\u00EDm re\u017Eimem je Voln\u00E9 psan\u00ED, ve kter\u00E9m v\u0161ichni hr\u00E1\u010Di p\u0159episuj\u00ED stejn\u00FD text. Na rychlosti z\u00E1le\u017E\u00ED, ale chyby sni\u017Euj\u00ED kone\u010Dn\u00E9 hodnocen\u00ED. P\u0159esn\u011Bj\u0161\u00ED hr\u00E1\u010D tak m\u016F\u017Ee vyhr\u00E1t, i kdy\u017E p\u00ED\u0161e o n\u011Bco pomaleji.",
              "Dal\u0161\u00ED re\u017Eimy umo\u017E\u0148uj\u00ED tr\u00E9novat jin\u00E9 dovednosti. N\u00E1hodn\u00E1 slova prov\u011B\u0159\u00ED tvoji obratnost p\u0159i psan\u00ED, Pam\u011B\u0165ov\u00FD \u0159et\u011Bzec vy\u017Eaduje zapamatov\u00E1n\u00ED po\u0159ad\u00ED slov a P\u0159e\u017Eit\u00ED klade d\u016Fraz na rychl\u00E9 reakce."),
            rule_section(:main_2, "Nastaven\u00ED",
              "Hru zah\u00E1j\u00ED\u0161 vytvo\u0159en\u00EDm hern\u00EDho stolu. M\u016F\u017Ee\u0161 ho p\u0159ipravit pro samostatn\u00FD tr\u00E9nink nebo pozvat dal\u0161\u00ED hr\u00E1\u010De.",
              "Nejd\u016Fle\u017Eit\u011Bj\u0161\u00ED je v\u00FDb\u011Br hern\u00EDho re\u017Eimu. Ka\u017Ed\u00FD ze \u010Dty\u0159 dostupn\u00FDch re\u017Eim\u016F nab\u00EDz\u00ED jin\u00FD druh v\u00FDzvy a umo\u017E\u0148uje p\u0159izp\u016Fsobit hru sv\u00FDm pot\u0159eb\u00E1m.",
              "Voln\u00E9 psan\u00ED spo\u010D\u00EDv\u00E1 v p\u0159episov\u00E1n\u00ED vybran\u00E9ho textu. M\u016F\u017Ee\u0161 pou\u017E\u00EDt p\u0159ipraven\u00E9 p\u0159\u00EDb\u011Bhy, vlastn\u00ED soubory nebo vlo\u017Een\u00FD text. V tomto re\u017Eimu lze tak\u00E9 omezit dobu psan\u00ED a p\u0159i samostatn\u00E9 h\u0159e vynechat p\u0159edlohu a ps\u00E1t vlastn\u00ED text.",
              "V re\u017Eimu N\u00E1hodn\u00E1 slova p\u00ED\u0161e\u0161 postupn\u011B slova, kter\u00E1 ti hra p\u0159edkl\u00E1d\u00E1. M\u016F\u017Ee\u0161 pou\u017E\u00EDt b\u011B\u017Enou kl\u00E1vesnici, braillsk\u00FD vstup nebo sm\u00ED\u0161en\u00FD re\u017Eim, kter\u00FD m\u011Bn\u00ED zp\u016Fsob zad\u00E1v\u00E1n\u00ED jednotliv\u00FDch slov.",
              "Pam\u011B\u0165ov\u00FD \u0159et\u011Bzec zkou\u0161\u00ED, jak dob\u0159e si dok\u00E1\u017Ee\u0161 zapamatovat prodlu\u017Euj\u00EDc\u00ED se \u0159adu slov. P\u0159i ka\u017Ed\u00E9m dal\u0161\u00EDm pokusu mus\u00ED\u0161 zopakovat v\u0161echna dosavadn\u00ED slova ve spr\u00E1vn\u00E9m po\u0159ad\u00ED.",
              "P\u0159e\u017Eit\u00ED kombinuje psan\u00ED n\u00E1hodn\u00FDch slov se z\u00E1vodem s \u010Dasem. Vybere\u0161 si obt\u00ED\u017Enost, kter\u00E1 ur\u010Duje po\u010D\u00E1te\u010Dn\u00ED tempo hry.",
              "Po nastaven\u00ED stolu m\u016F\u017Ee\u0161 za\u010D\u00EDt tr\u00E9novat nebo st\u016Fl zve\u0159ejnit, aby se mohli p\u0159ipojit ostatn\u00ED. K dispozici jsou b\u011B\u017En\u00E9 funkce PowerGames, nap\u0159\u00EDklad pozv\u00E1nky, sledov\u00E1n\u00ED hry, chat a historie her.",
              "Podrobn\u00E1 pravidla jednotliv\u00FDch re\u017Eim\u016F a jejich dostupn\u00E1 nastaven\u00ED najde\u0161 v kapitole Hern\u00ED re\u017Eimy a mo\u017Enosti stolu."),
            rule_section(:main_3, "Jak hr\u00E1t",
              "Na za\u010D\u00E1tku ka\u017Ed\u00E9ho nov\u00E9ho kola se zam\u011B\u0159en\u00ED automaticky vr\u00E1t\u00ED do pole pro psan\u00ED. Pokud se b\u011Bhem hry p\u0159esune\u0161 na jin\u00FD prvek rozhran\u00ED, vra\u0165 zam\u011B\u0159en\u00ED do tohoto pole, abys mohl pokra\u010Dovat.",
              "Hra p\u0159ed\u010D\u00EDt\u00E1 slova, kter\u00E1 m\u00E1\u0161 napsat. Podle re\u017Eimu m\u016F\u017Ee tak\u00E9 \u010D\u00EDst cel\u00E9 v\u011Bty nebo vy\u017Eadovat, aby sis vybavil d\u0159\u00EDve vyslechnut\u00E1 slova.",
              "Slovo obvykle potvrd\u00ED\u0161 stisknut\u00EDm mezern\u00EDku po jeho naps\u00E1n\u00ED. V\u00FDjimkou je P\u0159e\u017Eit\u00ED, kde se spr\u00E1vn\u011B dokon\u010Den\u00E9 slovo potvrd\u00ED automaticky.",
              "Tak\u00E9 pr\u00E1ce s chybami z\u00E1vis\u00ED na re\u017Eimu. Ve Voln\u00E9m psan\u00ED m\u016F\u017Ee\u0161 pr\u00E1v\u011B psan\u00E9 slovo opravovat kl\u00E1vesou Backspace, dokud ho nepotvrd\u00ED\u0161 mezern\u00EDkem. V ostatn\u00EDch re\u017Eimech hra kontroluje znaky pr\u016Fb\u011B\u017En\u011B a p\u0159i stisknut\u00ED nespr\u00E1vn\u00E9 kl\u00E1vesy nepokra\u010Duje d\u00E1l, ale \u010Dek\u00E1 na spr\u00E1vn\u00FD znak.",
              "B\u011Bhem hry si m\u016F\u017Ee\u0161 nechat slova p\u0159e\u010D\u00EDst (Ctrl+O) nebo vyhl\u00E1skovat (Ctrl+L) a dal\u0161\u00EDmi zkratkami opakovat \u010D\u00E1sti textu. V\u0161echny dostupn\u00E9 mo\u017Enosti najde\u0161 v seznamu kl\u00E1vesov\u00FDch zkratek.",
              "P\u0159i p\u0159episov\u00E1n\u00ED nemus\u00ED\u0161 dodr\u017Eovat velikost p\u00EDsmen ani p\u0159esn\u011B zad\u00E1vat v\u0161echny ozdobn\u00E9 typografick\u00E9 znaky. Hra p\u0159ij\u00EDm\u00E1 jejich jednodu\u0161\u0161\u00ED kl\u00E1vesnicov\u00E9 varianty. Plat\u00ED to pro r\u016Fzn\u00E9 druhy uvozovek, mezer, poml\u010Dek i v\u00FDpustku.\nPokud jsou v textu \u010D\u00EDsla, hra t\u011B upozorn\u00ED, \u017Ee je m\u00E1\u0161 napsat \u010D\u00EDslicemi.",
              "P\u0159i importu vlastn\u00EDho textu se tak\u00E9 dozv\u00ED\u0161, zda obsahuje nepodporovan\u00E9 znaky, kter\u00E9 je t\u0159eba zm\u011Bnit."),
            rule_section(:main_4, "Ukon\u010Den\u00ED hry",
              "Zp\u016Fsob ukon\u010Den\u00ED hry z\u00E1vis\u00ED na zvolen\u00E9m re\u017Eimu.",
              "Ve Voln\u00E9m psan\u00ED kolo kon\u010D\u00ED, kdy\u017E p\u0159ep\u00ED\u0161e\u0161 cel\u00FD text, vypr\u0161\u00ED nastaven\u00FD \u010Dasov\u00FD limit nebo zvol\u00ED\u0161 p\u0159\u00EDkaz Ukon\u010Dit psan\u00ED.",
              "V re\u017Eimech N\u00E1hodn\u00E1 slova, Pam\u011B\u0165ov\u00FD \u0159et\u011Bzec a P\u0159e\u017Eit\u00ED kolo kon\u010D\u00ED po p\u011Bti chyb\u00E1ch. M\u016F\u017Ee\u0161 ho tak\u00E9 ukon\u010Dit ru\u010Dn\u011B.",
              "Ve h\u0159e pro v\u00EDce hr\u00E1\u010D\u016F se v\u00FDsledky zobraz\u00ED, a\u017E v\u0161ichni dokon\u010D\u00ED hru. V\u00EDt\u011Bz\u00ED hr\u00E1\u010D s nejvy\u0161\u0161\u00EDm hodnocen\u00EDm. Pokud n\u011Bkolik hr\u00E1\u010D\u016F dos\u00E1hne stejn\u00E9ho v\u00FDsledku, jde o rem\u00EDzu.",
              "V z\u00E1pase na v\u00EDce kol rozhoduje o celkov\u00E9m v\u00EDt\u011Bzi po\u010Det vyhran\u00FDch kol.",
              "Psanom\u00E1nie oce\u0148uje jak dovednost p\u0159i psan\u00ED, tak p\u0159esnost. Kone\u010Dn\u00E9 hodnocen\u00ED proto nen\u00ED jen po\u010Det napsan\u00FDch slov.",
              "Ve Voln\u00E9m psan\u00ED je jedn\u00EDm z ukazatel\u016F WPM, tedy po\u010Det spr\u00E1vn\u011B napsan\u00FDch slov za minutu. Hra zapo\u010D\u00EDt\u00E1v\u00E1 \u010Das str\u00E1ven\u00FD psan\u00EDm, ale nezapo\u010D\u00EDt\u00E1v\u00E1 \u010Das poslechu p\u0159ed stisknut\u00EDm prvn\u00ED kl\u00E1vesy dan\u00E9ho slova. M\u016F\u017Ee\u0161 si tedy slovo nejprve v klidu poslechnout a ujistit se, co m\u00E1\u0161 napsat.",
              "V N\u00E1hodn\u00FDch slovech, Pam\u011B\u0165ov\u00E9m \u0159et\u011Bzci a P\u0159e\u017Eit\u00ED je z\u00E1kladem hodnocen\u00ED po\u010Det spr\u00E1vn\u011B napsan\u00FDch slov.",
              "Bez ohledu na re\u017Eim hra vypo\u010D\u00EDt\u00E1v\u00E1 tak\u00E9 koeficient p\u0159esnosti. Jde o po\u010Det spr\u00E1vn\u00FDch slov d\u011Blen\u00FD sou\u010Dtem spr\u00E1vn\u00FDch slov a chyb.",
              "Z\u00E1kladn\u00ED hodnocen\u00ED se pak t\u00EDmto koeficientem vyn\u00E1sob\u00ED dvakr\u00E1t.",
              "Nap\u0159\u00EDklad pokud spr\u00E1vn\u011B nap\u00ED\u0161e\u0161 20 slov a ud\u011Bl\u00E1\u0161 4 chyby, kone\u010Dn\u00E9 hodnocen\u00ED bude p\u0159ibli\u017En\u011B 13,89 bodu.",
              "Hr\u00E1\u010D, kter\u00FD nap\u00ED\u0161e 17 slov bez jedin\u00E9 chyby, z\u00EDsk\u00E1 17 bod\u016F a vyhraje.\nJak je vid\u011Bt, ps\u00E1t za ka\u017Edou cenu co nejrychleji se v\u017Edy nevyplat\u00ED. O n\u011Bco pomalej\u0161\u00ED, ale p\u0159esn\u011Bj\u0161\u00ED psan\u00ED m\u016F\u017Ee p\u0159in\u00E9st lep\u0161\u00ED v\u00FDsledek.\nV souhrnu se zobraz\u00ED kone\u010Dn\u00E9 hodnocen\u00ED a procentu\u00E1ln\u00ED p\u0159esnost."),
            rule_section(:main_5, "Hern\u00ED re\u017Eimy a mo\u017Enosti stolu",
              "Ka\u017Ed\u00FD re\u017Eim Psanom\u00E1nie m\u00E1 trochu jin\u00E1 pravidla. Rozd\u00EDly se t\u00FDkaj\u00ED nejen samotn\u00E9ho \u00FAkolu, ale tak\u00E9 opravov\u00E1n\u00ED chyb, potvrzov\u00E1n\u00ED slov a dostupn\u00FDch nastaven\u00ED."),
            rule_section(:main_6, "Voln\u00E9 psan\u00ED",
              "V tomto re\u017Eimu p\u0159episuje\u0161 vybran\u00FD text slovo po slov\u011B, b\u011B\u017En\u00FDm zp\u016Fsobem nebo pomoc\u00ED simulovan\u00E9ho braillsk\u00E9ho rozlo\u017Een\u00ED kl\u00E1vesnice. Ve h\u0159e pro v\u00EDce hr\u00E1\u010D\u016F dostanou v\u0161ichni stejnou p\u0159edlohu.",
              "Na za\u010D\u00E1tku hra p\u0159e\u010Dte aktu\u00E1ln\u00ED v\u011Btu a potom prvn\u00ED slovo, kter\u00E9 m\u00E1\u0161 napsat.",
              "Napi\u0161 ho p\u0159esn\u011B, v\u010Detn\u011B interpunkce, a stiskni mezern\u00EDk pro pokra\u010Dov\u00E1n\u00ED.",
              "Dokud slovo nepotvrd\u00ED\u0161, m\u016F\u017Ee\u0161 ho opravovat kl\u00E1vesou Backspace. Po stisknut\u00ED mezern\u00EDku hra slovo vyhodnot\u00ED a p\u0159ejde na dal\u0161\u00ED.",
              "Pokud ud\u011Bl\u00E1\u0161 chybu, usly\u0161\u00ED\u0161 charakteristick\u00FD zvuk a ozn\u00E1men\u00ED, ale hra bude pokra\u010Dovat.\nM\u016F\u017Ee\u0161 pou\u017E\u00EDt p\u0159ipraven\u00E9 texty ze seznamu v nastaven\u00ED stolu, importovat vlastn\u00ED soubory nebo vlo\u017Eit libovoln\u00FD text.\nPo v\u00FDb\u011Bru textu se v popisu stolu objev\u00ED jeho n\u00E1zev a po\u010Det znak\u016F v\u010Detn\u011B mezer. Tyto \u00FAdaje uvid\u00ED\u0161 tak\u00E9 ve widgetu stolu, tak\u017Ee ostatn\u00ED mohou je\u0161t\u011B p\u0159ed p\u0159ipojen\u00EDm odhadnout d\u00E9lku hry.",
              "Chce\u0161-li pou\u017E\u00EDt vlastn\u00ED text, vyber Vlo\u017Eit text. V nastaven\u00ED stolu napi\u0161 jeho n\u00E1zev a kl\u00E1vesou Tab p\u0159ejdi do pole s obsahem.",
              "Importovan\u00E9 soubory mus\u00ED b\u00FDt v k\u00F3dov\u00E1n\u00ED UTF-8. Maxim\u00E1ln\u00ED velikost souboru nebo vlo\u017Een\u00E9ho textu je 1000 kB. Proto\u017Ee n\u011Bkter\u00E9 znaky zab\u00EDraj\u00ED v\u00EDce ne\u017E jeden bajt, jde o o n\u011Bco m\u00E9n\u011B ne\u017E milion znak\u016F. Tv\u00E9 texty se ukl\u00E1daj\u00ED m\u00EDstn\u011B v po\u010D\u00EDta\u010Di. Pokud ale vlastn\u00ED text pou\u017Eije\u0161 ve h\u0159e pro v\u00EDce hr\u00E1\u010D\u016F, bude p\u0159i zah\u00E1jen\u00ED hry prost\u0159ednictv\u00EDm serveru Elten zp\u0159\u00EDstupn\u011Bn \u00FA\u010Dastn\u00EDk\u016Fm.\nVe v\u00FDchoz\u00EDm nastaven\u00ED Voln\u00E9 psan\u00ED trv\u00E1 a\u017E do konce cel\u00E9ho textu. Pokud chce\u0161 krat\u0161\u00ED hru, m\u016F\u017Ee\u0161 nastavit \u010Dasov\u00FD limit. Jakmile vypr\u0161\u00ED, kolo skon\u010D\u00ED, i kdy\u017E bude\u0161 pr\u00E1v\u011B uprost\u0159ed slova.\nP\u0159i samostatn\u00E9 h\u0159e m\u016F\u017Ee\u0161 tak\u00E9 ps\u00E1t bez p\u0159edlohy. Nam\u00EDsto p\u0159episov\u00E1n\u00ED p\u0159ipraven\u00E9ho textu tak p\u00ED\u0161e\u0161 vlastn\u00ED obsah. Pokud nenastav\u00ED\u0161 \u010Dasov\u00FD limit, m\u016F\u017Ee\u0161 ps\u00E1t tak dlouho, jak chce\u0161. Pro ukon\u010Den\u00ED takov\u00E9 relace vyber Ukon\u010Dit psan\u00ED.\nP\u0159i samostatn\u00E9m p\u0159episov\u00E1n\u00ED p\u0159ipraven\u00E9ho textu si hra m\u00EDstn\u011B zapamatuje tv\u016Fj postup, kdy\u017E skon\u010D\u00ED\u0161 nebo hru opust\u00ED\u0161. Pozd\u011Bji tak m\u016F\u017Ee\u0161 nav\u00E1zat bez nutnosti za\u010D\u00EDnat stejn\u00FD text od za\u010D\u00E1tku. Chce\u0161-li si ho zopakovat cel\u00FD, v \u010D\u00E1sti M\u00EDstn\u00ED texty a postup vynuluj sv\u016Fj postup."),
            rule_section(:main_7, "N\u00E1hodn\u00E1 slova",
              "V tomto re\u017Eimu hra postupn\u011B p\u0159ed\u010D\u00EDt\u00E1 n\u00E1hodn\u011B vybran\u00E1 slova. Tv\u00FDm \u00FAkolem je ka\u017Ed\u00E9 spr\u00E1vn\u011B napsat a potvrdit mezern\u00EDkem.",
              "Na rozd\u00EDl od Voln\u00E9ho psan\u00ED se spr\u00E1vnost kontroluje po ka\u017Ed\u00E9m znaku. Pokud stiskne\u0161 nespr\u00E1vnou kl\u00E1vesu, p\u0159i\u010Dte se jedna chyba, ale kurzor se neposune. Pro pokra\u010Dov\u00E1n\u00ED mus\u00ED\u0161 zadat spr\u00E1vn\u00FD znak.",
              "Backspace nefunguje, proto\u017Ee chybn\u00E9 znaky se nep\u0159id\u00E1vaj\u00ED ke spr\u00E1vn\u011B napsan\u00E9mu za\u010D\u00E1tku slova.",
              "Ve h\u0159e pro v\u00EDce hr\u00E1\u010D\u016F nav\u00EDc plat\u00ED p\u011Btisekundov\u00FD limit ne\u010Dinnosti.\nPokud do t\u00E9 doby neza\u010Dne\u0161 ps\u00E1t nebo nebude\u0161 pokra\u010Dovat, dostane\u0161 chybu. \u010Casova\u010D b\u011B\u017E\u00ED i p\u0159ed stisknut\u00EDm prvn\u00ED kl\u00E1vesy.",
              "P\u0159\u00EDslu\u0161nou kl\u00E1vesovou zkratkou si m\u016F\u017Ee\u0161 nechat slovo p\u0159e\u010D\u00EDst nebo vyhl\u00E1skovat. Po dobu \u0159e\u010Di ode\u010D\u00EDta\u010De obrazovky se \u010Dasova\u010D zastav\u00ED a po jej\u00EDm skon\u010Den\u00ED z\u00EDsk\u00E1\u0161 znovu cel\u00FDch p\u011Bt sekund.",
              "V samostatn\u00E9 h\u0159e nen\u00ED za ne\u010Dinnost \u017E\u00E1dn\u00FD postih, tak\u017Ee m\u016F\u017Ee\u0161 cvi\u010Dit vlastn\u00EDm tempem.\nV nastaven\u00ED tohoto re\u017Eimu si m\u016F\u017Ee\u0161 vybrat b\u011B\u017Enou kl\u00E1vesnici, braillsk\u00FD vstup nebo sm\u00ED\u0161en\u00FD re\u017Eim.",
              "Ve sm\u00ED\u0161en\u00E9m re\u017Eimu hra pro ka\u017Ed\u00E9 slovo n\u00E1hodn\u011B vybere zp\u016Fsob zad\u00E1v\u00E1n\u00ED.",
              "Podrobnosti o braillsk\u00E9m vstupu najde\u0161 d\u00E1le v t\u00E9to kapitole."),
            rule_section(:main_9, "Pam\u011B\u0165ov\u00FD \u0159et\u011Bzec",
              "V tomto re\u017Eimu si zapamatov\u00E1v\u00E1\u0161 st\u00E1le del\u0161\u00ED \u0159adu slov.",
              "Nejprve ti hra p\u0159edlo\u017E\u00ED jedno slovo, kter\u00E9 mus\u00ED\u0161 napsat. Potom p\u0159id\u00E1 dal\u0161\u00ED, ale p\u0159e\u010Dte jen nov\u011B p\u0159idan\u00E9 slovo.",
              "Poka\u017Ed\u00E9 mus\u00ED\u0161 zopakovat cel\u00FD \u0159et\u011Bzec od za\u010D\u00E1tku a jednotliv\u00E1 slova odd\u011Blovat mezern\u00EDkem.",
              "Nap\u0159\u00EDklad kdy\u017E nejprve usly\u0161\u00ED\u0161 \u201Eko\u010Dka\u201C a potom \u201Ezahrada\u201C, mus\u00ED\u0161 napsat ob\u011B slova ve spr\u00E1vn\u00E9m po\u0159ad\u00ED. Jakmile p\u0159ibude t\u0159et\u00ED slovo, nap\u00ED\u0161e\u0161 v\u0161echna t\u0159i.",
              "Ka\u017Ed\u00FD dal\u0161\u00ED pokus je obt\u00ED\u017En\u011Bj\u0161\u00ED, proto\u017Ee si mus\u00ED\u0161 pamatovat v\u00EDce slov.",
              "Stejn\u011B jako v N\u00E1hodn\u00FDch slovech chybn\u00FD znak p\u0159id\u00E1 chybu, ale neposune kurzor a kl\u00E1vesu Backspace nelze pou\u017E\u00EDt. Tak\u00E9 v tomto re\u017Eimu plat\u00ED stejn\u00FD postih za ne\u010Dinnost a je mo\u017En\u00E9 ps\u00E1t braillem.",
              "Sm\u00ED\u0161en\u00FD re\u017Eim je v tomto p\u0159\u00EDpad\u011B pro nevyl\u00E9\u010Diteln\u00E9 nerdy, proto\u017Ee si mus\u00ED\u0161 pamatovat nejen slovo, ale i zp\u016Fsob, jak\u00FDm se m\u011Blo napsat."),
            rule_section(:main_10, "Re\u017Eim p\u0159e\u017Eit\u00ED",
              "V P\u0159e\u017Eit\u00ED mus\u00ED\u0161 napsat ka\u017Ed\u00E9 dal\u0161\u00ED slovo d\u0159\u00EDve, ne\u017E dohraje hudba.",
              "Ka\u017Ed\u00E9 slovo m\u00E1 vlastn\u00ED \u010Dasov\u00FD limit dan\u00FD d\u00E9lkou nahr\u00E1vky.",
              "V nastaven\u00ED stolu si m\u016F\u017Ee\u0161 zvolit jednu ze t\u0159\u00ED obt\u00ED\u017Enost\u00ED.",
              "- Lehk\u00E1 - na za\u010D\u00E1tku p\u0159ibli\u017En\u011B 16 sekund.\n- St\u0159edn\u00ED - na za\u010D\u00E1tku p\u0159ibli\u017En\u011B 10,67 sekundy.\n- T\u011B\u017Ek\u00E1 - na za\u010D\u00E1tku p\u0159ibli\u017En\u011B 6,64 sekundy.",
              "Po ka\u017Ed\u00E9m spr\u00E1vn\u011B dokon\u010Den\u00E9m slov\u011B se hudba zrychl\u00ED o 2,5 procenta a zv\u00FD\u0161\u00ED se jej\u00ED t\u00F3n.",
              "\u010C\u00EDm d\u00E9le tedy hraje\u0161 bez chyb, t\u00EDm m\u00E9n\u011B \u010Dasu m\u00E1\u0161 na dal\u0161\u00ED slova.\nV tomto re\u017Eimu slova nepotvrzuje\u0161 mezern\u00EDkem. Jakmile nap\u00ED\u0161e\u0161 posledn\u00ED spr\u00E1vn\u00FD znak, hra automaticky p\u0159ejde na dal\u0161\u00ED slovo.",
              "Pokud stiskne\u0161 nespr\u00E1vnou kl\u00E1vesu, p\u0159i\u010Dte se chyba, ale spr\u00E1vn\u011B napsan\u00FD za\u010D\u00E1tek slova ti z\u016Fstane.",
              "Kdy\u017E hudba dohraje d\u0159\u00EDve, ne\u017E slovo dokon\u010D\u00ED\u0161, hra p\u0159id\u00E1 chybu a zah\u00E1j\u00ED nov\u00E9 slovo. V takov\u00E9m p\u0159\u00EDpad\u011B se hudba nezrychl\u00ED.\nPamatuj, \u017Ee p\u0159ed\u010D\u00EDt\u00E1n\u00ED, hl\u00E1skov\u00E1n\u00ED ani ztlumen\u00ED hudby nezastavuj\u00ED odpo\u010D\u00EDt\u00E1v\u00E1n\u00ED \u010Dasu.",
              "Dal\u0161\u00ED \u010Dasova\u010D ne\u010Dinnosti tu nen\u00ED, proto\u017Ee \u010Das pro ka\u017Ed\u00E9 slovo ur\u010Duje samotn\u00E1 hudba.",
              "I zde m\u016F\u017Ee\u0161 pou\u017E\u00EDvat b\u011B\u017Enou kl\u00E1vesnici, braillsk\u00FD vstup nebo sm\u00ED\u0161en\u00FD re\u017Eim."),
            rule_section(:main_11, "Psan\u00ED braillem",
              "M\u00EDsto zad\u00E1v\u00E1n\u00ED znak\u016F jednotliv\u00FDmi kl\u00E1vesami m\u016F\u017Ee\u0161 pou\u017E\u00EDt rozlo\u017Een\u00ED napodobuj\u00EDc\u00ED braillskou kl\u00E1vesnici.",
              "Braillsk\u00FDm bod\u016Fm odpov\u00EDdaj\u00ED tyto kl\u00E1vesy.",
              "- Body 1, 2 a 3 - F, D, S.\n- Body 4, 5 a 6 - J, K, L.\n- Bod 7 - A.\n- Bod 8 - st\u0159edn\u00EDk.",
              "Chce\u0161-li zadat braillsk\u00FD znak, stiskni odpov\u00EDdaj\u00EDc\u00ED kl\u00E1vesy sou\u010Dasn\u011B a pak je uvolni.\nV Nastaven\u00ED Psanom\u00E1nie si m\u016F\u017Ee\u0161 vybrat r\u016Fzn\u00E9 braillsk\u00E9 tabulky pro sv\u016Fj jazyk nebo m\u00EDstn\u00ED tabulku Liblouis ulo\u017Eenou jako soubor ctb, utb, tbl \u010Di uti."),
            rule_section(:main_12, "Nastaven\u00ED Psanom\u00E1nie",
              "Nastaven\u00ED Psanom\u00E1nie otev\u0159e\u0161 stisknut\u00EDm Ctrl+P.",
              "Najde\u0161 tu mo\u017Enosti pro braillsk\u00FD vstup, odezvu p\u0159i psan\u00ED, upozorn\u011Bn\u00ED na chyby a hlasitost hudby.",
              "Odezva p\u0159i psan\u00ED ur\u010Duje, co ti hra b\u011Bhem psan\u00ED p\u0159ed\u010D\u00EDt\u00E1.",
              "M\u016F\u017Ee\u0161 ponechat nastaven\u00ED Eltenu, zvolit p\u0159ed\u010D\u00EDt\u00E1n\u00ED znak\u016F, slov, znak\u016F i slov nebo odezvu \u00FApln\u011B vypnout.",
              "Tyto zm\u011Bny se vztahuj\u00ED pouze na pole pro psan\u00ED b\u011Bhem hry.\nDal\u0161\u00ED nastaven\u00ED ur\u010Duje, jak t\u011B hra upozorn\u00ED na chyby.",
              "Hlasov\u00E1 a zvukov\u00E1 upozorn\u011Bn\u00ED jsou nez\u00E1visl\u00E1. M\u016F\u017Ee\u0161 zapnout ob\u011B, vybrat jen jednu mo\u017Enost nebo upozorn\u011Bn\u00ED zcela vypnout.\nPosledn\u00ED mo\u017Enost\u00ED je posuvn\u00EDk hlasitosti hudby v rozsahu od 0 do 100 procent."),
            rule_section(:main_13, "Kola a z\u00E1pasy pro v\u00EDce hr\u00E1\u010D\u016F",
              "V re\u017Eimech N\u00E1hodn\u00E1 slova, Pam\u011B\u0165ov\u00FD \u0159et\u011Bzec a P\u0159e\u017Eit\u00ED m\u016F\u017Ee\u0161 zvolit pevn\u00FD po\u010Det kol nebo z\u00E1pas, kter\u00FD trv\u00E1, dokud ho hostitel neukon\u010D\u00ED.",
              "V ka\u017Ed\u00E9m kole hr\u00E1\u010Di z\u00EDsk\u00E1vaj\u00ED body podle pravidel zvolen\u00E9ho re\u017Eimu.",
              "V z\u00E1pase na v\u00EDce kol rozhoduje o celkov\u00E9m v\u00EDt\u011Bzi po\u010Det vyhran\u00FDch kol.",
              "M\u016F\u017Ee\u0161 tak uspo\u0159\u00E1dat kr\u00E1tkou hru i del\u0161\u00ED turnaj, ve kter\u00E9m jedno zav\u00E1h\u00E1n\u00ED nemus\u00ED rozhodnout o celkov\u00E9m v\u00FDsledku."),
            rule_section(:touch_0, "Psan\u00ED v\u0161emi deseti",
              "Psan\u00ED naslepo spo\u010D\u00EDv\u00E1 v psan\u00ED textu bez d\u00EDv\u00E1n\u00ED se na kl\u00E1vesnici. Pravideln\u00FDm tr\u00E9ninkem se nau\u010D\u00ED\u0161 nach\u00E1zet kl\u00E1vesy automaticky, co\u017E m\u016F\u017Ee zlep\u0161it rychlost, p\u0159esnost i pohodl\u00ED p\u0159i psan\u00ED. Tuto metodu se u\u010D\u00ED lid\u00E9 z r\u016Fzn\u00FDch profes\u00ED, ve kter\u00FDch rychlost psan\u00ED p\u0159\u00EDmo ovliv\u0148uje produktivitu pr\u00E1ce, nap\u0159\u00EDklad program\u00E1to\u0159i, novin\u00E1\u0159i nebo spisovatel\u00E9."),
            rule_section(:touch_1, "Z\u00E1kladn\u00ED pravidla",
              "Polo\u017E prsty lev\u00E9 ruky na kl\u00E1vesy A, S, D, F a prsty prav\u00E9 ruky na J, K, L, \u016E. Palce polo\u017E na mezern\u00EDk.",
              "Na kl\u00E1ves\u00E1ch F a J najde\u0161 mal\u00E9 hmatov\u00E9 v\u00FDstupky, kter\u00E9 ti pomohou naj\u00EDt v\u00FDchoz\u00ED polohu obou rukou bez d\u00EDv\u00E1n\u00ED se na kl\u00E1vesnici.",
              "Jedn\u00E1 se o z\u00E1kladn\u00ED polohu, ze kter\u00E9 m\u016F\u017Ee\u0161 ps\u00E1t dal\u0161\u00ED znaky p\u0159esouv\u00E1n\u00EDm prst\u016F na sousedn\u00ED kl\u00E1vesy. Pokud chce\u0161 nap\u0159\u00EDklad napsat p\u00EDsmeno y, posu\u0148 mal\u00ED\u010Dek lev\u00E9 ruky z kl\u00E1vesy a dol\u016F. Pro naps\u00E1n\u00ED q posu\u0148 stejn\u00FD prst nahoru. P\u00EDsmeno z vy\u017Eaduje p\u0159esunut\u00ED ukazov\u00E1\u010Dku prav\u00E9 ruky z kl\u00E1vesy j \u0161ikmo nahoru doleva."),
            rule_section(:touch_2, "P\u011Bt zlat\u00FDch pravidel psan\u00ED naslepo",
              "1. Pou\u017E\u00EDvej v\u0161echny prsty. Ka\u017Ed\u00FD prst m\u00E1 p\u0159i\u0159azen\u00E9 ur\u010Dit\u00E9 kl\u00E1vesy. P\u0159i u\u010Den\u00ED se sna\u017E toto rozd\u011Blen\u00ED dodr\u017Eovat.",
              "2. Vracej se do v\u00FDchoz\u00ED polohy. Po stisknut\u00ED kl\u00E1vesy vra\u0165 prst na jeho z\u00E1kladn\u00ED m\u00EDsto. Nap\u0159\u00EDklad po naps\u00E1n\u00ED p\u00EDsmene r vra\u0165 ukazov\u00E1\u010Dek lev\u00E9 ruky zp\u011Bt na f.",
              "3. Pou\u017E\u00EDvej palec pro mezern\u00EDk. Pro psan\u00ED velk\u00FDch p\u00EDsmen pou\u017E\u00EDvej kl\u00E1vesu Shift na opa\u010Dn\u00E9 stran\u011B kl\u00E1vesnice. Nap\u0159\u00EDklad pro velk\u00E9 A pou\u017Eij prav\u00FD Shift a pro velk\u00E9 K lev\u00FD Shift.",
              "4. Nenap\u00EDnej ruce. Prov\u00E1d\u011Bj lehk\u00E9, uvoln\u011Bn\u00E9 pohyby a udr\u017Euj z\u00E1p\u011Bst\u00ED pokud mo\u017Eno v p\u0159irozen\u00E9, rovn\u00E9 poloze.",
              "5. Nesp\u011Bchej. Nejprve se nau\u010D ps\u00E1t p\u0159esn\u011B. Rychlost p\u0159ijde postupn\u011B s prax\u00ED."),
            rule_section(:touch_3, "Jak efektivn\u011B tr\u00E9novat?",
              "Tr\u00E9nuj pravideln\u011B. Na za\u010D\u00E1tek vyzkou\u0161ej kr\u00E1tk\u00E9 tr\u00E9ninky v d\u00E9lce p\u0159ibli\u017En\u011B 10-15 minut.",
              "Zam\u011B\u0159 se na p\u0159esnost. Nejprve se sna\u017E minimalizovat po\u010Det chyb v textu a teprve potom postupn\u011B zvy\u0161uj rychlost psan\u00ED.",
              "Opakuj obt\u00ED\u017En\u00E9 kombinace. Pokud ti n\u011Bkter\u00E1 kl\u00E1vesa nebo slovo d\u011Bl\u00E1 pot\u00ED\u017Ee, v\u011Bnuj jim v\u00EDce \u010Dasu.",
              "Sleduj sv\u016Fj pokrok. Porovn\u00E1vej sv\u00E9 v\u00FDsledky z jednotliv\u00FDch tr\u00E9nink\u016F, ale pamatuj, \u017Ee samotn\u00E1 rychlost nen\u00ED nejd\u016Fle\u017Eit\u011Bj\u0161\u00ED.",
              "D\u011Blej si p\u0159est\u00E1vky. Pokud ztr\u00E1c\u00ED\u0161 soust\u0159ed\u011Bn\u00ED nebo c\u00EDt\u00ED\u0161 nepohodl\u00ED v rukou, p\u0159eru\u0161 tr\u00E9nink a odpo\u010Di\u0148 si."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "- Ctrl+L: Vyhl\u00E1skovat aktu\u00E1ln\u00ED slovo.",
              "- Ctrl+O: P\u0159e\u010D\u00EDst aktu\u00E1ln\u00ED slovo.",
              "- Ctrl+;: P\u0159e\u010D\u00EDst zbytek slova (nedostupn\u00E9 v pam\u011B\u0165ov\u00E9m \u0159et\u011Bzci).",
              "- Ctrl+Shift+;: P\u0159e\u010D\u00EDst zbytek v\u011Bty (voln\u00E9 psan\u00ED).",
              "- Alt+S: P\u0159e\u010D\u00EDst pr\u016Fb\u011Bh.",
              "- Ctrl+P: Otev\u0159\u00EDt nastaven\u00ED psan\u00ED.",
              "- Space: Potvrdit slovo (krom\u011B p\u0159e\u017Eit\u00ED).",
              "- Backspace: Opravit aktu\u00E1ln\u00ED slovo (voln\u00E9 psan\u00ED).",
              "- Ctrl+S: Ulo\u017Eit a zav\u0159\u00EDt st\u016Fl.",
              "- F1: Kontextov\u00E1 n\u00E1pov\u011Bda.",
              "- Ctrl+F1: N\u00E1pov\u011Bda hry.",
              "- Escape: Opustit st\u016Fl.")
          ]
        when "en"
          [
            rule_section(:main_0, "Typoholism",
              "Typoholism is a game where you can practise your typing speed, accuracy and memory. You can play on your own, compete with friends or simply track your progress.",
              "There are several modes to choose from, ranging from leisurely story transcription to challenges where every second counts. This guide explains how to start a game, how each mode works and what to pay attention to while typing."),
            rule_section(:main_1, "Objective",
              "Your goal is to type as quickly as possible while making as few mistakes as you can. Depending on the mode, you'll transcribe a prepared text, type random words, remember increasingly long word sequences or race against the clock.\nYou can play alone or with up to seven other people. In multiplayer, players compete for the best score, with victory depending on both the average number of correctly typed words per minute and accuracy, measured by the number of mistakes made.",
              "The main mode is Free Typing, where everyone transcribes the same text. Speed matters, but mistakes reduce your final score, so a more accurate player can win even if they type a little more slowly.",
              "The other modes let you practise different skills. Random Words tests your typing skills, Memory Chain challenges you to remember words in order, and Survival puts your reactions to the test."),
            rule_section(:main_2, "Setup",
              "Start by creating a game table. You can set it up for solo practice or invite other players to join you.",
              "Your most important choice is the game mode. Each of the four modes offers a different kind of challenge and lets you tailor the game to your preferences.",
              "Free Typing involves transcribing a selected text. You can use the built-in stories, your own files or pasted text. You can also set a time limit or, when playing solo, dispense with the source text and write something of your own.",
              "Random Words challenges you to type words presented by the game one at a time. You can use a regular keyboard, Braille input or a mixed mode that changes the input method from word to word.",
              "Memory Chain tests how well you can remember a growing sequence of words. With each attempt, you must reproduce all the words presented so far in the correct order.",
              "Survival combines typing random words with a race against the clock. You choose a difficulty level that determines the starting pace.",
              "Once you've configured the table, you can begin practising or publish it so that others can join. Standard PowerGames features are available, including invitations, spectating, chat and game history.",
              "You'll find the detailed rules for each mode and its available settings in the Game modes and table options section."),
            rule_section(:main_3, "How to play",
              "At the start of each new round, focus automatically returns to the typing field. If you move to another part of the interface during play, return focus to that field to continue.",
              "The game reads out the words you need to type. Depending on the mode, it may also read entire sentences or ask you to recall words you heard earlier.",
              "Usually, you confirm a word by pressing Space after typing it. The exception is Survival, where a correctly completed word is confirmed automatically.",
              "Mistakes are handled differently depending on the mode. In Free Typing, you can correct the current word with Backspace until you confirm it with Space. In the other modes, the game checks each character as you type. If you press an incorrect key, it waits for the correct one instead of moving on.",
              "During play, you can have words read aloud (Ctrl+O) or spelled out (Ctrl+L), and use other shortcuts to repeat parts of the text. Check the shortcuts list to discover all the available commands.",
              "When transcribing texts, you don't have to match letter case or reproduce every decorative typographic character. The game accepts simpler keyboard equivalents for all types of quotation marks, spaces, dashes and ellipses.\nIf the text contains numbers, the game will tell you to enter them as digits.",
              "When you import your own text, you'll also be notified of any unsupported characters that need changing."),
            rule_section(:main_4, "Ending a game",
              "How a game ends depends on the selected mode.",
              "In Free Typing, a round ends when you finish transcribing the text, the set time limit expires, or you choose End Typing.",
              "In Random Words, Memory Chain and Survival, a round ends after five mistakes. You can also end it manually.",
              "In multiplayer, the results appear once everyone has finished. The player with the highest score wins. If two or more players have exactly the same score, it's a tie.",
              "In a match consisting of multiple rounds, the overall winner is determined by the number of rounds won.",
              "Typoholism rewards both typing proficiency and accuracy. That's why your final score isn't simply the number of words you typed.",
              "In Free Typing, one measure of performance is WPM, or correctly typed words per minute. The game counts the time spent typing them, but not the time spent listening before you press the first key of a word. You can therefore listen to the whole word first to make sure you know what to type.",
              "In Random Words, Memory Chain and Survival, the score is based on the number of correctly typed words.",
              "In every mode, the game also calculates an accuracy factor. This is the number of correct words divided by the total of correct words and mistakes.",
              "The base score is then multiplied by that accuracy factor twice.",
              "For example, if you type 20 words correctly and make 4 mistakes, your final score will be approximately 13.89 points.",
              "Someone who types 17 words without a single mistake will score 17 points and win.\nAs you can see, typing as fast as possible isn't always the best strategy. A slightly slower but more accurate approach can pay off.\nThe summary displays your final score and accuracy percentage."),
            rule_section(:main_5, "Game modes and table options",
              "Each Typoholism mode has slightly different rules. The differences involve not only the task itself, but also how mistakes are corrected, how words are confirmed and which settings are available."),
            rule_section(:main_6, "Free Typing",
              "In this mode, you transcribe a selected text word by word, either using regular typing or by simulating a Braille keyboard layout. In multiplayer, everyone receives the same text.",
              "At the beginning, the game reads the current sentence, followed by the first word you need to type.",
              "Type it exactly, including punctuation, and press Space to continue.",
              "Until you confirm a word, you can correct it with Backspace. Once you press Space, the game checks the word and moves on to the next one.",
              "If you make a mistake, you'll hear a distinctive sound and a message, but the game will continue.\nYou can choose from built-in texts in the table settings, import your own files or paste any text.\nOnce you select a text, its title and character count, including spaces, appear in the table description. They are also displayed in the table widget, allowing other players to estimate the length of the game before joining.",
              "To use your own material, choose Paste Text. Enter its title in the table settings, then press Tab to move to the text field.",
              "Imported files must use UTF-8 encoding. The maximum size of a file or pasted text is 1,000 kB. Since some characters take up more than one byte, this corresponds to slightly fewer than a million characters. Your texts are stored locally on your computer. However, if you use your own text in multiplayer, it is shared with the participants through the Elten server when the game starts.\nBy default, Free Typing continues until the entire text is finished. If you'd prefer a shorter game, you can set a time limit. When it expires, the round ends even if you're in the middle of a word.\nWhen playing solo, you can also choose to type without a source text. Instead of transcribing something prepared, you write your own text. Without a time limit, you can keep writing for as long as you like. To finish such a session, choose End Typing.\nWhen transcribing a built-in text on your own, the game saves your progress locally when you finish or leave. This lets you resume later rather than starting the same text again. If you want to repeat it from the beginning, reset its progress in Local Texts and Progress."),
            rule_section(:main_7, "Random Words",
              "In this mode, the game reads out randomly selected words one after another. Your task is to type each one correctly and confirm it with Space.",
              "Unlike Free Typing, each character is checked as soon as you enter it. If you press the wrong key, you make one mistake, but the cursor stays in place. You must enter the correct character to continue.",
              "Backspace doesn't work because incorrect characters aren't added to the correctly typed beginning of the word.",
              "Multiplayer games also have a five-second inactivity limit.\nIf you don't start typing or continue typing within that time, you receive a mistake. The timer also runs before you press the first key.",
              "You can use the appropriate shortcut to have the word read aloud or spelled out. The timer pauses while the screen reader is speaking, and once it finishes, you get a full five seconds again.",
              "There is no inactivity penalty when playing solo, so you can practise at your own pace.\nIn this mode's settings, you can choose a regular keyboard, Braille input or mixed mode.",
              "In mixed mode, the game randomly selects an input method for each word.",
              "You'll find more information about Braille input later in this guide."),
            rule_section(:main_9, "Memory Chain",
              "This mode is about remembering an increasingly long sequence of words.",
              "First, the game gives you one word to type. It then adds another, but reads aloud only the new word.",
              "Each time, you must reproduce the entire sequence from the beginning, separating the words with Space.",
              "For example, if you first hear \u201Ccat\u201D and then \u201Cgarden\u201D, you must type both words in the correct order. When a third word is added, you type all three.",
              "Each attempt gets harder as there are more words to remember.",
              "As in Random Words, an incorrect character adds one mistake but doesn't move the cursor, and Backspace isn't available. This mode also has the same inactivity penalty and supports Braille input.",
              "Mixed mode here is for incurable nerds, because you have to recall both the word and the way you were supposed to type it."),
            rule_section(:main_10, "Survival mode",
              "In Survival, you need to type each new word before the music stops playing.",
              "Each word has its own time limit, determined by the length of the recording.",
              "You can choose one of three difficulty levels in the table settings.",
              "- Easy - approximately 16 seconds at the start.\n- Medium - approximately 10.67 seconds at the start.\n- Hard - approximately 6.64 seconds at the start.",
              "After every correctly completed word, the music speeds up by 2.5 percent and its pitch rises.",
              "This means that the longer you play without mistakes, the less time you have to type each new word.\nIn this mode, you don't confirm words with Space. As soon as you type the last correct character, the game moves to the next word automatically.",
              "If you press the wrong key, you get a mistake but keep the correctly typed beginning of the word.",
              "If the music ends before you've finished a word, the game adds a mistake and starts a new word. In that case, the music doesn't speed up.\nRemember that reading words aloud, spelling them out and muting the music do not stop the countdown.",
              "There is no separate inactivity timer here, because the music itself sets the time limit for each word.",
              "You can also use a regular keyboard, Braille input or mixed mode here."),
            rule_section(:main_11, "Braille input",
              "Instead of entering characters with individual keys, you can use a layout that simulates a Braille keyboard.",
              "Braille dots correspond to the following keys.",
              "- Dots 1, 2 and 3 - F, D, S.\n- Dots 4, 5 and 6 - J, K, L.\n- Dot 7 - A.\n- Dot 8 - semicolon.",
              "To enter a Braille character, press the corresponding keys together, then release them.\nIn Typoholism Settings, you can choose different Braille tables for your language, or a local Liblouis table provided as a ctb, utb, tbl or uti file."),
            rule_section(:main_12, "Typoholism Settings",
              "Press Ctrl+P to open Typoholism Settings.",
              "Here you can configure Braille input, typing echo, error notifications and music volume.",
              "Typing echo controls what the game reads aloud as you type.",
              "You can follow Elten's settings, have characters read aloud, have words read aloud, hear both characters and words, or turn echo off entirely.",
              "These changes apply only to the typing field during the game.\nAnother setting controls how the game informs you about mistakes.",
              "Spoken and sound notifications are independent. You can enable both, choose just one or turn notifications off completely.\nThe final option is a music volume slider ranging from 0 to 100 percent."),
            rule_section(:main_13, "Rounds and multiplayer matches",
              "In Random Words, Memory Chain and Survival, you can choose a fixed number of rounds or play a match that continues until the host ends it.",
              "In each round, players earn scores according to the rules of the selected mode.",
              "In a multi-round match, the overall winner is the player who wins the most rounds.",
              "This allows for both a quick game and a longer tournament in which a single setback doesn't necessarily decide the final result."),
            rule_section(:touch_0, "Touch typing",
              "Touch typing means entering text without looking at the keyboard. With regular practice, you'll learn to find keys automatically, which can improve your typing speed, accuracy, and comfort. Touch typing is a valuable skill for people in many professions where typing speed directly affects productivity, such as programmers, journalists, and writers."),
            rule_section(:touch_1, "Basic Principles",
              "Place the fingers of your left hand on the A, S, D, and F keys, and those of your right hand on J, K, L, and the semicolon (;). Rest your thumbs on the spacebar.",
              "The F and J keys have small raised bumps that help you find the starting position for both hands without looking.",
              "This is your home position. From here, you can type other characters by moving your fingers to nearby keys. For example, to type z, move your left pinky down from a. To type q, move the same finger up. To type y, move your right index finger diagonally up and to the left from j."),
            rule_section(:touch_2, "Five Golden Rules of Touch Typing",
              "1. Use all your fingers. Each finger is assigned specific keys. Try to follow these assignments while learning.",
              "2. Return to the home position. After pressing a key, move your finger back to its starting position. For example, after typing r, return your left index finger to f.",
              "3. Use your thumb for the spacebar. For capital letters, use the Shift key on the opposite side of the keyboard. For example, use the right Shift key to type A, and the left Shift key to type K.",
              "4. Keep your hands relaxed. Make light, natural movements and keep your wrists as straight as comfortably possible.",
              "5. Don't rush. Focus on accuracy first. Speed will come with practice."),
            rule_section(:touch_3, "How to Practice Effectively",
              "Practice regularly. Start with short sessions lasting around 10-15 minutes.",
              "Focus on accuracy. Try to minimize typing errors before gradually increasing your speed.",
              "Repeat difficult combinations. If a particular key or word gives you trouble, spend some extra time practicing it.",
              "Track your progress. Compare your results across training sessions, but remember that speed isn't everything.",
              "Take breaks. If you start losing concentration or feel discomfort in your hands, stop practicing and rest."),
            rule_section(:controls, "Keyboard shortcuts",
              "- Ctrl+L: Spell the current word.",
              "- Ctrl+O: Read the current word.",
              "- Ctrl+;: Read the rest of the word (unavailable in Memory Chain).",
              "- Ctrl+Shift+;: Read the rest of the sentence (Free Typing).",
              "- Alt+S: Read progress.",
              "- Ctrl+P: Open typing settings.",
              "- Space: Confirm the word (except Survival).",
              "- Backspace: Correct the current word (Free Typing).",
              "- Ctrl+S: Save and close the table.",
              "- F1: Contextual help.",
              "- Ctrl+F1: Game help.",
              "- Escape: Leave the table.")
          ]
        when "es"
          [
            rule_section(:main_0, "Teclaman\u00EDa",
              "Teclaman\u00EDa es un juego con el que puedes practicar la velocidad al teclear, la precisi\u00F3n y la memoria. Puedes jugar por tu cuenta, competir con tus amigos o simplemente comprobar tus progresos.",
              "Tienes varios modos entre los que elegir, desde transcribir relatos tranquilamente hasta afrontar retos en los que cada segundo cuenta. Aqu\u00ED descubrir\u00E1s c\u00F3mo empezar una partida, c\u00F3mo funciona cada modo y a qu\u00E9 debes prestar atenci\u00F3n mientras escribes."),
            rule_section(:main_1, "Objetivo del juego",
              "Tu objetivo es escribir lo m\u00E1s r\u00E1pido posible y cometer el menor n\u00FAmero de errores. Seg\u00FAn el modo que elijas, tendr\u00E1s que transcribir un texto, teclear palabras aleatorias, memorizar secuencias de palabras cada vez m\u00E1s largas o competir contra el reloj.\nPuedes jugar en solitario o con un m\u00E1ximo de otras siete personas. En las partidas multijugador, los participantes compiten por conseguir la mejor puntuaci\u00F3n. La victoria depende tanto de la media de palabras escritas correctamente por minuto como de la precisi\u00F3n, medida por el n\u00FAmero de errores cometidos.",
              "El modo principal es Escritura libre, en el que todos los jugadores transcriben el mismo texto. La velocidad importa, pero los errores reducen la puntuaci\u00F3n final. Por eso, un jugador m\u00E1s preciso puede ganar incluso si escribe algo m\u00E1s despacio.",
              "Los dem\u00E1s modos permiten entrenar otras habilidades. Palabras aleatorias pone a prueba tu soltura al teclear, Cadena de memoria exige recordar palabras en orden y Supervivencia se centra en la rapidez de reacci\u00F3n."),
            rule_section(:main_2, "Configuraci\u00F3n",
              "Para empezar, crea una mesa de juego. Puedes prepararla para practicar en solitario o invitar a otros jugadores.",
              "La decisi\u00F3n m\u00E1s importante es elegir el modo de juego. Cada uno de los cuatro modos disponibles ofrece un reto diferente y permite adaptar la partida a tus preferencias.",
              "Escritura libre consiste en transcribir un texto elegido. Puedes utilizar los relatos incluidos, tus propios archivos o un texto pegado. Tambi\u00E9n puedes limitar el tiempo de escritura o, si juegas en solitario, prescindir del texto de referencia y escribir algo propio.",
              "En Palabras aleatorias debes teclear, una tras otra, las palabras que te indica el juego. Puedes usar un teclado normal, la entrada braille o un modo mixto que cambia la forma de introducir cada palabra.",
              "Cadena de memoria comprueba hasta qu\u00E9 punto recuerdas una secuencia de palabras que va creciendo. En cada intento tienes que reproducir todas las palabras anteriores en el orden correcto.",
              "Supervivencia combina la escritura de palabras aleatorias con una carrera contrarreloj. Puedes elegir el nivel de dificultad, que determina el ritmo inicial de la partida.",
              "Una vez configurada la mesa, puedes empezar a practicar o publicarla para que se unan otros participantes. Dispones de las funciones habituales de PowerGames, como invitaciones, espectadores, chat e historial de partidas.",
              "Encontrar\u00E1s las reglas detalladas de cada modo y sus ajustes disponibles en el apartado Modos de juego y opciones de la mesa."),
            rule_section(:main_3, "C\u00F3mo jugar",
              "Al comienzo de cada ronda, el foco vuelve autom\u00E1ticamente al campo de escritura. Si durante la partida te desplazas a otro elemento de la interfaz, vuelve a situar el foco en ese campo para continuar.",
              "El juego lee en voz alta las palabras que tienes que escribir. Seg\u00FAn el modo, tambi\u00E9n puede leer frases enteras o pedirte que recuerdes palabras que ya has escuchado.",
              "Normalmente, despu\u00E9s de escribir una palabra, la confirmas pulsando la barra espaciadora. La excepci\u00F3n es Supervivencia, donde las palabras completadas correctamente se confirman autom\u00E1ticamente.",
              "La gesti\u00F3n de los errores tambi\u00E9n depende del modo. En Escritura libre puedes corregir la palabra actual con Retroceso hasta que la confirmes con la barra espaciadora. En los dem\u00E1s modos, el juego comprueba los caracteres a medida que escribes y, si pulsas una tecla incorrecta, espera a que pulses la correcta en lugar de avanzar.",
              "Durante la partida puedes hacer que el juego lea las palabras (Ctrl+O) o las deletree (Ctrl+L), adem\u00E1s de usar otros atajos para repetir fragmentos del texto. Consulta la lista de atajos para conocer todas las opciones.",
              "Al transcribir textos no tienes que respetar las may\u00FAsculas y min\u00FAsculas ni reproducir todos los signos tipogr\u00E1ficos especiales. El juego admite equivalentes m\u00E1s sencillos que puedes escribir con el teclado. Esto se aplica a los distintos tipos de comillas, espacios, guiones y puntos suspensivos.\nSi el texto contiene n\u00FAmeros, el juego te indicar\u00E1 que debes introducirlos con cifras.",
              "Al importar un texto propio, tambi\u00E9n se te avisar\u00E1 si contiene caracteres no admitidos que debas cambiar."),
            rule_section(:main_4, "Fin de la partida",
              "La forma de terminar depende del modo elegido.",
              "En Escritura libre, una ronda termina cuando acabas de transcribir el texto, se agota el l\u00EDmite de tiempo establecido o seleccionas Terminar de escribir.",
              "En Palabras aleatorias, Cadena de memoria y Supervivencia, la ronda termina cuando cometes cinco errores. Tambi\u00E9n puedes finalizarla manualmente.",
              "En multijugador, los resultados se muestran cuando todos los participantes han terminado. Gana quien obtiene la puntuaci\u00F3n m\u00E1s alta. Si varios jugadores consiguen exactamente la misma puntuaci\u00F3n, hay empate.",
              "En las partidas de varias rondas, la victoria final depende del n\u00FAmero de rondas ganadas.",
              "Teclaman\u00EDa recompensa tanto la habilidad para teclear como la precisi\u00F3n. Por eso, la puntuaci\u00F3n final no es simplemente el n\u00FAmero de palabras escritas.",
              "En Escritura libre, una de las medidas del rendimiento es el WPM, es decir, las palabras escritas correctamente por minuto. El juego tiene en cuenta el tiempo dedicado a escribirlas, pero no el tiempo de escucha anterior a la primera pulsaci\u00F3n de cada palabra. As\u00ED puedes escucharla tranquilamente y asegurarte de lo que tienes que escribir.",
              "En Palabras aleatorias, Cadena de memoria y Supervivencia, la puntuaci\u00F3n se basa en el n\u00FAmero de palabras escritas correctamente.",
              "Independientemente del modo, el juego tambi\u00E9n calcula un coeficiente de precisi\u00F3n. Se obtiene dividiendo el n\u00FAmero de palabras correctas entre la suma de palabras correctas y errores.",
              "Despu\u00E9s, la puntuaci\u00F3n base se multiplica dos veces por ese coeficiente.",
              "Por ejemplo, si escribes correctamente 20 palabras y cometes 4 errores, tu puntuaci\u00F3n final ser\u00E1 de unos 13,89 puntos.",
              "Una persona que escriba 17 palabras sin cometer ning\u00FAn error obtendr\u00E1 17 puntos y ganar\u00E1.\nComo puedes ver, escribir lo m\u00E1s r\u00E1pido posible no siempre compensa. A veces es mejor ir un poco m\u00E1s despacio y ser m\u00E1s preciso.\nEl resumen muestra la puntuaci\u00F3n final y el porcentaje de precisi\u00F3n."),
            rule_section(:main_5, "Modos de juego y opciones de la mesa",
              "Cada modo de Teclaman\u00EDa tiene unas reglas ligeramente distintas. Las diferencias no se limitan a la tarea en s\u00ED, sino que tambi\u00E9n afectan a la correcci\u00F3n de errores, la confirmaci\u00F3n de palabras y los ajustes disponibles."),
            rule_section(:main_6, "Escritura libre",
              "En este modo transcribes un texto elegido palabra por palabra, utilizando el teclado de forma habitual o simulando una distribuci\u00F3n de teclado braille. En multijugador, todos los participantes reciben el mismo material.",
              "Al principio, el juego lee la frase actual y luego la primera palabra que debes escribir.",
              "Escr\u00EDbela exactamente, incluidos los signos de puntuaci\u00F3n, y pulsa la barra espaciadora para continuar.",
              "Mientras no hayas confirmado la palabra, puedes corregirla con Retroceso. Al pulsar la barra espaciadora, el juego eval\u00FAa lo escrito y pasa a la siguiente palabra.",
              "Si cometes un error, oir\u00E1s un sonido caracter\u00EDstico y un aviso, pero la partida continuar\u00E1.\nPuedes elegir entre los textos incluidos en los ajustes de la mesa, importar tus propios archivos o pegar cualquier contenido.\nAl seleccionar un texto, su t\u00EDtulo y el n\u00FAmero de caracteres, incluidos los espacios, aparecen en la descripci\u00F3n de la mesa. Esta informaci\u00F3n tambi\u00E9n se muestra en el widget, para que los dem\u00E1s jugadores puedan calcular la duraci\u00F3n aproximada de la partida antes de unirse.",
              "Si quieres usar tu propio material, selecciona Pegar texto. En la pantalla de configuraci\u00F3n, escribe el t\u00EDtulo y despu\u00E9s pulsa Tab para ir al campo de contenido.",
              "Los archivos importados deben estar codificados en UTF-8. El tama\u00F1o m\u00E1ximo de un archivo o texto pegado es de 1000 kB. Como algunos caracteres ocupan m\u00E1s de un byte, esto equivale a algo menos de un mill\u00F3n de caracteres. Tus textos se guardan localmente en tu ordenador. Sin embargo, si utilizas un texto propio en multijugador, se compartir\u00E1 con los participantes a trav\u00E9s del servidor de Elten al comenzar la partida.\nPor defecto, Escritura libre dura hasta que se termina el texto completo. Si prefieres una partida m\u00E1s corta, puedes establecer un l\u00EDmite de tiempo. Cuando se agote, la ronda terminar\u00E1 aunque est\u00E9s a mitad de una palabra.\nSi juegas en solitario, tambi\u00E9n puedes escribir sin texto de referencia. En lugar de transcribir contenido preparado, escribes lo que quieras. Si no estableces un l\u00EDmite de tiempo, puedes continuar todo el tiempo que desees. Para terminar esa sesi\u00F3n, selecciona Terminar de escribir.\nCuando transcribes un texto incluido en el juego en solitario, el programa guarda tu progreso localmente al terminar o salir. As\u00ED puedes continuar m\u00E1s adelante sin tener que empezar otra vez desde el principio. Si quieres repetir el texto completo, restablece el progreso en Textos locales y progreso."),
            rule_section(:main_7, "Palabras aleatorias",
              "En este modo, el juego lee palabras seleccionadas al azar una detr\u00E1s de otra. Tu tarea consiste en escribirlas correctamente y confirmar cada una con la barra espaciadora.",
              "A diferencia de Escritura libre, cada car\u00E1cter se comprueba en el momento de introducirlo. Si pulsas una tecla equivocada, cometes un error, pero el cursor no avanza. Debes introducir el car\u00E1cter correcto para continuar.",
              "Retroceso no funciona porque los caracteres incorrectos no se a\u00F1aden al comienzo de la palabra que ya has escrito bien.",
              "En las partidas multijugador tambi\u00E9n se aplica un l\u00EDmite de inactividad de cinco segundos.\nSi no empiezas a escribir o no contin\u00FAas dentro de ese tiempo, se registra un error. El contador tambi\u00E9n funciona antes de pulsar la primera tecla.",
              "Puedes usar el atajo correspondiente para escuchar la palabra o hacer que se deletree. El contador se detiene mientras habla el lector de pantalla y, cuando termina, vuelves a disponer de cinco segundos completos.",
              "En solitario no hay penalizaci\u00F3n por inactividad, as\u00ED que puedes practicar a tu ritmo.\nEn los ajustes de este modo puedes elegir entre un teclado normal, entrada braille o modo mixto.",
              "En el modo mixto, el juego elige al azar el m\u00E9todo de entrada para cada palabra.",
              "Encontrar\u00E1s m\u00E1s informaci\u00F3n sobre la entrada braille m\u00E1s adelante en este apartado."),
            rule_section(:main_9, "Cadena de memoria",
              "Este modo consiste en recordar una secuencia de palabras cada vez m\u00E1s larga.",
              "Al principio, el juego te dice una palabra que debes escribir. Despu\u00E9s a\u00F1ade otra, pero solo lee en voz alta la nueva.",
              "Cada vez debes reproducir la secuencia completa desde el principio, separando las palabras con la barra espaciadora.",
              "Por ejemplo, si primero oyes \u00ABgato\u00BB y despu\u00E9s \u00ABjard\u00EDn\u00BB, tienes que escribir ambas palabras en el orden correcto. Cuando aparezca una tercera palabra, deber\u00E1s escribir las tres.",
              "Con cada intento aumenta la dificultad, porque tienes que recordar m\u00E1s palabras.",
              "Al igual que en Palabras aleatorias, un car\u00E1cter incorrecto suma un error, pero no mueve el cursor, y no se puede utilizar Retroceso. En este modo tambi\u00E9n se aplica la misma penalizaci\u00F3n por inactividad y se puede escribir en braille.",
              "En este caso, el modo mixto es para nerds incurables, porque hay que recordar tanto la palabra como la forma en que hab\u00EDa que escribirla."),
            rule_section(:main_10, "Modo supervivencia",
              "En Supervivencia, tu objetivo es escribir las palabras antes de que termine la m\u00FAsica.",
              "Cada palabra tiene su propio l\u00EDmite de tiempo, determinado por la duraci\u00F3n de la grabaci\u00F3n.",
              "En los ajustes de la mesa puedes elegir entre tres niveles de dificultad.",
              "- F\u00E1cil - aproximadamente 16 segundos al principio.\n- Medio - aproximadamente 10,67 segundos al principio.\n- Dif\u00EDcil - aproximadamente 6,64 segundos al principio.",
              "Despu\u00E9s de cada palabra completada correctamente, la m\u00FAsica se acelera un 2,5 por ciento y sube de tono.",
              "Esto significa que, cuanto m\u00E1s tiempo juegues sin errores, menos tiempo tendr\u00E1s para escribir las siguientes palabras.\nEn este modo no confirmas las palabras con la barra espaciadora. Cuando introduces el \u00FAltimo car\u00E1cter correcto, el juego pasa autom\u00E1ticamente a la siguiente palabra.",
              "Si pulsas una tecla incorrecta, se registra un error, pero conservas el comienzo de la palabra que hab\u00EDas escrito bien.",
              "Si la m\u00FAsica termina antes de que completes la palabra, el juego suma un error y empieza una nueva palabra. En ese caso, la m\u00FAsica no se acelera.\nRecuerda que escuchar la palabra, deletrearla o silenciar la m\u00FAsica no detiene el tiempo.",
              "Aqu\u00ED no hay un contador de inactividad adicional, porque es la propia m\u00FAsica la que determina el tiempo disponible para cada palabra.",
              "Tambi\u00E9n puedes utilizar un teclado normal, la entrada braille o el modo mixto."),
            rule_section(:main_11, "Escritura en braille",
              "En lugar de introducir los caracteres pulsando una tecla cada vez, puedes utilizar una distribuci\u00F3n que simula un teclado braille.",
              "Los puntos braille se corresponden con las siguientes teclas.",
              "- Puntos 1, 2 y 3 - F, D, S.\n- Puntos 4, 5 y 6 - J, K, L.\n- Punto 7 - A.\n- Punto 8 - punto y coma.",
              "Para introducir un car\u00E1cter braille, pulsa a la vez las teclas correspondientes y despu\u00E9s su\u00E9ltalas.\nEn los Ajustes de Teclaman\u00EDa puedes elegir distintas tablas braille para tu idioma o una tabla local de Liblouis indicada como archivo ctb, utb, tbl o uti."),
            rule_section(:main_12, "Ajustes de Teclaman\u00EDa",
              "Pulsa Ctrl+P para abrir los Ajustes de Teclaman\u00EDa.",
              "Encontrar\u00E1s opciones relacionadas con el braille, el eco de escritura, los avisos de errores y el volumen de la m\u00FAsica.",
              "El eco de escritura determina lo que el juego lee en voz alta mientras tecleas.",
              "Puedes utilizar la configuraci\u00F3n de Elten o elegir que se lean los caracteres, las palabras, ambos o desactivar el eco por completo.",
              "Estos cambios solo afectan al campo de escritura durante la partida.\nOtro ajuste permite decidir c\u00F3mo te informa el juego de los errores.",
              "Los avisos hablados y los sonidos son independientes. Puedes activar ambos, usar solo uno o desactivar todas las notificaciones.\nLa \u00FAltima opci\u00F3n es un control deslizante para ajustar el volumen de la m\u00FAsica entre el 0 y el 100 por ciento."),
            rule_section(:main_13, "Rondas y partidas multijugador",
              "En Palabras aleatorias, Cadena de memoria y Supervivencia puedes elegir un n\u00FAmero fijo de rondas o una partida que contin\u00FAe hasta que el anfitri\u00F3n decida terminarla.",
              "En cada ronda, los jugadores consiguen puntuaciones seg\u00FAn las reglas del modo elegido.",
              "Si eliges una partida de varias rondas, la victoria final depende del n\u00FAmero de rondas ganadas.",
              "As\u00ED puedes organizar tanto partidas cortas como torneos m\u00E1s largos, en los que un solo tropiezo no tiene por qu\u00E9 decidir el resultado final."),
            rule_section(:touch_0, "Mecanograf\u00EDa al tacto",
              "La mecanograf\u00EDa al tacto consiste en escribir sin mirar el teclado. Con la pr\u00E1ctica regular, aprender\u00E1s a encontrar las teclas de forma autom\u00E1tica, lo que puede mejorar tu velocidad, precisi\u00F3n y comodidad al escribir. Es una t\u00E9cnica que aprenden personas de numerosas profesiones en las que la velocidad de escritura influye directamente en la productividad, como programadores, periodistas y escritores."),
            rule_section(:touch_1, "Principios b\u00E1sicos",
              "Coloca los dedos de la mano izquierda sobre las teclas A, S, D y F, y los de la mano derecha sobre J, K, L y \u00D1. Apoya los pulgares sobre la barra espaciadora.",
              "Las teclas F y J tienen peque\u00F1as marcas en relieve que te ayudan a encontrar la posici\u00F3n inicial de ambas manos sin mirar el teclado.",
              "Esta es la posici\u00F3n de referencia, desde la que puedes escribir otros caracteres moviendo los dedos hacia las teclas cercanas. Por ejemplo, para escribir la letra z, mueve el me\u00F1ique izquierdo hacia abajo desde la tecla a. Para escribir q, mueve el mismo dedo hacia arriba. Para escribir la letra y, desplaza el dedo \u00EDndice derecho en diagonal hacia arriba y a la izquierda desde la tecla j."),
            rule_section(:touch_2, "Las cinco reglas de oro de la mecanograf\u00EDa al tacto",
              "1. Utiliza todos los dedos. Cada dedo tiene asignadas determinadas teclas. Intenta respetar esta distribuci\u00F3n mientras aprendes.",
              "2. Vuelve a la posici\u00F3n inicial. Despu\u00E9s de pulsar una tecla, devuelve el dedo a su posici\u00F3n de referencia. Por ejemplo, despu\u00E9s de escribir la letra r, vuelve a colocar el \u00EDndice izquierdo sobre la tecla f.",
              "3. Utiliza el pulgar para la barra espaciadora. Para escribir may\u00FAsculas, usa la tecla Shift del lado opuesto del teclado. Por ejemplo, para escribir A, utiliza el Shift derecho y, para escribir K, el izquierdo.",
              "4. Mant\u00E9n las manos relajadas. Realiza movimientos suaves y naturales, procurando mantener las mu\u00F1ecas lo m\u00E1s rectas posible, sin forzarlas.",
              "5. No tengas prisa. Primero aprende a escribir con precisi\u00F3n. La velocidad llegar\u00E1 con la pr\u00E1ctica."),
            rule_section(:touch_3, "\u00BFC\u00F3mo practicar de forma eficaz?",
              "Practica con regularidad. Para empezar, prueba sesiones cortas de unos 10-15 minutos.",
              "Da prioridad a la precisi\u00F3n. Intenta reducir al m\u00EDnimo los errores al escribir antes de aumentar gradualmente la velocidad.",
              "Repite las combinaciones dif\u00EDciles. Si alguna tecla o palabra te resulta complicada, dedica un poco m\u00E1s de tiempo a practicarla.",
              "Observa tu progreso. Compara tus resultados entre sesiones de entrenamiento, pero recuerda que la velocidad no es lo \u00FAnico importante.",
              "Haz descansos. Si notas que pierdes la concentraci\u00F3n o sientes molestias en las manos, interrumpe la pr\u00E1ctica y descansa."),
            rule_section(:controls, "Atajos de teclado",
              "- Ctrl+L: Deletrear la palabra actual.",
              "- Ctrl+O: Leer la palabra actual.",
              "- Ctrl+;: Leer el resto de la palabra (no disponible en Cadena de memoria).",
              "- Ctrl+Shift+;: Leer el resto de la frase (Escritura libre).",
              "- Alt+S: Leer el progreso.",
              "- Ctrl+P: Abrir los ajustes de escritura.",
              "- Space: Confirmar la palabra (excepto Supervivencia).",
              "- Backspace: Corregir la palabra actual (Escritura libre).",
              "- Ctrl+S: Guardar y cerrar la mesa.",
              "- F1: Ayuda contextual.",
              "- Ctrl+F1: Ayuda del juego.",
              "- Escape: Salir de la mesa.")
          ]
        when "pl"
          [
            rule_section(:main_0, "Mania pisania",
              "Mania pisania to gra, w kt\u00F3rej mo\u017Cesz \u0107wiczy\u0107 szybko\u015B\u0107 pisania, dok\u0142adno\u015B\u0107 i pami\u0119\u0107. Mo\u017Cesz gra\u0107 samodzielnie, rywalizowa\u0107 ze znajomymi albo po prostu sprawdza\u0107 w\u0142asne post\u0119py.",
              "Do wyboru masz kilka wariant\u00F3w, od spokojnego przepisywania opowiada\u0144 po wyzwania, w kt\u00F3rych liczy si\u0119 ka\u017Cda sekunda. Poni\u017Cej dowiesz si\u0119, jak rozpocz\u0105\u0107 rozgrywk\u0119, jak dzia\u0142aj\u0105 poszczeg\u00F3lne warianty i na co zwraca\u0107 uwag\u0119 podczas pisania."),
            rule_section(:main_1, "Cel gry",
              "Twoim zadaniem jest pisa\u0107 mo\u017Cliwie szybko i pope\u0142nia\u0107 jak najmniej b\u0142\u0119d\u00F3w. W zale\u017Cno\u015Bci od wybranego wariantu b\u0119dziesz przepisywa\u0107 gotowy tekst, wpisywa\u0107 losowe s\u0142owa, zapami\u0119tywa\u0107 coraz d\u0142u\u017Csze ci\u0105gi albo \u015Bciga\u0107 si\u0119 z up\u0142ywaj\u0105cym czasem.\nMo\u017Cesz gra\u0107 samodzielnie lub z maksymalnie siedmioma innymi osobami. W grze wieloosobowej uczestnicy rywalizuj\u0105 o jak najlepszy wynik, a zwyci\u0119stwo zale\u017Cy zar\u00F3wno od \u015Bredniej liczby poprawnie wpisanych s\u0142\u00F3w na minut\u0119, jak i dok\u0142adno\u015Bci mierzonej poprzez liczb\u0119 pope\u0142nionych b\u0142\u0119d\u00F3w.",
              "Podstawowym wariantem jest Swobodne pisanie, w kt\u00F3rym wszyscy gracze przepisuj\u0105 ten sam tekst. Liczy si\u0119 tutaj tempo pisania, ale b\u0142\u0119dy obni\u017Caj\u0105 ko\u0144cow\u0105 ocen\u0119, dlatego dok\u0142adniejszy gracz mo\u017Ce wygra\u0107 nawet wtedy, gdy pisze nieco wolniej.",
              "Pozosta\u0142e warianty pozwalaj\u0105 \u0107wiczy\u0107 inne umiej\u0119tno\u015Bci. Losowe s\u0142owa sprawdzaj\u0105 sprawno\u015B\u0107 pisania, \u0141a\u0144cuch pami\u0119ciowy wymaga zapami\u0119tywania kolejno\u015Bci s\u0142\u00F3w, a Przetrwanie stawia na szybko\u015B\u0107 reagowania."),
            rule_section(:main_2, "Konfiguracja",
              "Rozgrywk\u0119 rozpoczynasz od utworzenia sto\u0142u. Mo\u017Cesz przygotowa\u0107 go do samodzielnego treningu albo zaprosi\u0107 innych graczy do wsp\u00F3lnej zabawy.",
              "Najwa\u017Cniejszym wyborem jest wariant gry. Ka\u017Cdy z czterech dost\u0119pnych tryb\u00F3w oferuje inny rodzaj wyzwania i pozwala dostosowa\u0107 rozgrywk\u0119 do Twoich potrzeb.",
              "Swobodne pisanie polega na przepisywaniu wybranego tekstu. Mo\u017Cesz korzysta\u0107 z gotowych opowiada\u0144, w\u0142asnych plik\u00F3w lub wklejonej tre\u015Bci. W tym wariancie mo\u017Cesz te\u017C ograniczy\u0107 czas pisania, a podczas samodzielnej gry zrezygnowa\u0107 z tekstu \u017Ar\u00F3d\u0142owego i pisa\u0107 w\u0142asn\u0105 tre\u015B\u0107.",
              "Losowe s\u0142owa to \u0107wiczenie polegaj\u0105ce na wpisywaniu kolejnych s\u0142\u00F3w podawanych przez gr\u0119. Mo\u017Cesz korzysta\u0107 ze zwyk\u0142ej klawiatury, brajla albo trybu mieszanego, kt\u00F3ry zmienia spos\u00F3b wpisywania poszczeg\u00F3lnych s\u0142\u00F3w.",
              "\u0141a\u0144cuch pami\u0119ciowy sprawdza, jak dobrze zapami\u0119tujesz wyd\u0142u\u017Caj\u0105cy si\u0119 ci\u0105g s\u0142\u00F3w. W ka\u017Cdej kolejnej pr\u00F3bie musisz odtworzy\u0107 wszystkie dotychczasowe s\u0142owa w odpowiedniej kolejno\u015Bci.",
              "Przetrwanie \u0142\u0105czy pisanie losowych s\u0142\u00F3w z wy\u015Bcigiem z czasem. Wybierasz poziom trudno\u015Bci, od kt\u00F3rego zale\u017Cy pocz\u0105tkowe tempo rozgrywki.",
              "Po skonfigurowaniu sto\u0142u mo\u017Cesz rozpocz\u0105\u0107 trening albo opublikowa\u0107 st\u00F3\u0142, aby do\u0142\u0105czyli do niego inni uczestnicy. Do dyspozycji masz standardowe funkcje PowerGames, takie jak zaproszenia, obserwowanie, czat i historia rozgrywki.",
              "Szczeg\u00F3\u0142owe zasady poszczeg\u00F3lnych wariant\u00F3w oraz dost\u0119pne w nich ustawienia znajdziesz w rozdziale Warianty i opcje sto\u0142u."),
            rule_section(:main_3, "Jak gra\u0107",
              "Po rozpocz\u0119ciu ka\u017Cdej nowej rundy fokus automatycznie wraca do pola pisania. Je\u015Bli w trakcie rozgrywki przejdziesz do innego elementu interfejsu, ustaw go ponownie w tym polu, aby kontynuowa\u0107.",
              "Gra odczytuje s\u0142owa, kt\u00F3re nale\u017Cy wpisa\u0107. W zale\u017Cno\u015Bci od wariantu mo\u017Ce r\u00F3wnie\u017C odczytywa\u0107 ca\u0142e zdania lub wymaga\u0107 zapami\u0119tania wcze\u015Bniej us\u0142yszanych s\u0142\u00F3w.",
              "Zwykle po wpisaniu s\u0142owa zatwierdzasz je Spacj\u0105. Wyj\u0105tkiem jest Przetrwanie, w kt\u00F3rym poprawnie uko\u0144czone s\u0142owo zostaje zatwierdzone automatycznie.",
              "Spos\u00F3b obs\u0142ugi b\u0142\u0119d\u00F3w r\u00F3wnie\u017C zale\u017Cy od wariantu. W Swobodnym pisaniu mo\u017Cesz poprawia\u0107 wpisywane s\u0142owo Backspace'em, dop\u00F3ki nie zatwierdzisz go Spacj\u0105. W pozosta\u0142ych wariantach gra sprawdza znaki na bie\u017C\u0105co i nie przechodzi dalej po wpisaniu niew\u0142a\u015Bciwego znaku, nadal czekaj\u0105c na poprawny klawisz.",
              "W trakcie gry mo\u017Cesz korzysta\u0107 z odczytywania s\u0142\u00F3w (ctrl+o) oraz ich literowania (ctrl+l), a tak\u017Ce innych skr\u00F3t\u00F3w do powtarzania fragment\u00F3w tekstu. Zajrzyj na list\u0119 skr\u00F3t\u00F3w, aby zapozna\u0107 si\u0119 ze wszystkimi mo\u017Cliwo\u015Bciami.",
              "Podczas przepisywania tekst\u00F3w nie musisz odtwarza\u0107 wielko\u015Bci liter ani wszystkich ozdobnych znak\u00F3w typograficznych. Gra akceptuje ich prostsze odpowiedniki dost\u0119pne na klawiaturze. Dotyczy to wszystkich odmian cudzys\u0142ow\u00F3w, spacji, my\u015Blnik\u00F3w oraz wielokropka.\nJe\u015Bli w tek\u015Bcie wyst\u0119puj\u0105 liczby, gra poinformuje Ci\u0119, \u017Ce nale\u017Cy wpisa\u0107 je cyframi.",
              "Podczas importowania w\u0142asnego tekstu otrzymasz r\u00F3wnie\u017C informacj\u0119 o ewentualnych nieobs\u0142ugiwanych znakach, kt\u00F3re trzeba zmieni\u0107."),
            rule_section(:main_4, "Ko\u0144czenie gry",
              "Spos\u00F3b zako\u0144czenia rozgrywki zale\u017Cy od wybranego wariantu.",
              "W Swobodnym pisaniu runda ko\u0144czy si\u0119 po przepisaniu ca\u0142ego tekstu, up\u0142ywie ustawionego limitu czasu albo wybraniu polecenia Zako\u0144cz pisanie.",
              "W Losowych s\u0142owach, \u0141a\u0144cuchu pami\u0119ciowym i Przetrwaniu runda ko\u0144czy si\u0119 po pope\u0142nieniu pi\u0119ciu b\u0142\u0119d\u00F3w. Mo\u017Cesz r\u00F3wnie\u017C zako\u0144czy\u0107 j\u0105 samodzielnie.",
              "W grze wieloosobowej wyniki zostan\u0105 przedstawione po zako\u0144czeniu rozgrywki przez wszystkich uczestnik\u00F3w. Zwyci\u0119\u017Ca osoba z najwy\u017Csz\u0105 ocen\u0105. Je\u015Bli kilku graczy osi\u0105gnie identyczny wynik, nast\u0119puje remis.",
              "W przypadku meczu wielorundowego o ko\u0144cowym zwyci\u0119stwie decyduje liczba wygranych rund.",
              "Mania pisania premiuje zar\u00F3wno sprawno\u015B\u0107 pisania, jak i dok\u0142adno\u015B\u0107. Dlatego ko\u0144cowa ocena nie jest po prostu liczb\u0105 wpisanych s\u0142\u00F3w.",
              "W Swobodnym pisaniu jedn\u0105 z miar wyniku jest WPM, czyli liczba poprawnie wpisanych s\u0142\u00F3w na minut\u0119. Gra uwzgl\u0119dnia czas po\u015Bwi\u0119cony na ich wpisywanie, ale nie liczy czasu s\u0142uchania przed naci\u015Bni\u0119ciem pierwszego klawisza danego s\u0142owa. Mo\u017Cesz wi\u0119c najpierw spokojnie wys\u0142ucha\u0107 s\u0142owa i upewni\u0107 si\u0119, co nale\u017Cy wpisa\u0107.",
              "W Losowych s\u0142owach, \u0141a\u0144cuchu pami\u0119ciowym i Przetrwaniu podstaw\u0105 wyniku jest liczba poprawnie wpisanych s\u0142\u00F3w.",
              "Niezale\u017Cnie od wariantu gra oblicza r\u00F3wnie\u017C wsp\u00F3\u0142czynnik dok\u0142adno\u015Bci. Jest to liczba poprawnych s\u0142\u00F3w podzielona przez sum\u0119 poprawnych s\u0142\u00F3w i pope\u0142nionych b\u0142\u0119d\u00F3w.",
              "Nast\u0119pnie wynik bazowy zostaje dwukrotnie pomno\u017Cony przez ten wsp\u00F3\u0142czynnik.",
              "Przyk\u0142adowo, je\u015Bli wpiszesz 20 poprawnych s\u0142\u00F3w i pope\u0142nisz 4 b\u0142\u0119dy, Twoja ko\u0144cowa ocena wyniesie oko\u0142o 13,89 punktu.",
              "Osoba, kt\u00F3ra wpisze 17 s\u0142\u00F3w bez \u017Cadnego b\u0142\u0119du, otrzyma 17 punkt\u00F3w i wygra.\nJak zatem \u0142atwo zauwa\u017Cy\u0107, nie zawsze op\u0142aca si\u0119 pisa\u0107 jak najszybciej. Czasami lepszym rozwi\u0105zaniem jest nieco spokojniejsze, ale dok\u0142adniejsze pisanie.\nPodsumowanie pokazuje ko\u0144cow\u0105 ocen\u0119 oraz wsp\u00F3\u0142czynnik dok\u0142adno\u015Bci w procentach."),
            rule_section(:main_5, "Warianty i opcje sto\u0142u",
              "Ka\u017Cdy wariant Manii pisania dzia\u0142a na nieco innych zasadach. R\u00F3\u017Cnice dotycz\u0105 nie tylko samego zadania, ale r\u00F3wnie\u017C sposobu poprawiania b\u0142\u0119d\u00F3w, zatwierdzania s\u0142\u00F3w i dost\u0119pnych ustawie\u0144."),
            rule_section(:main_6, "Swobodne pisanie",
              "W tym wariancie przepisujesz wybrany tekst s\u0142owo po s\u0142owie zwyczajnie lub symuluj\u0105c uk\u0142ad brajlowski. W grze wieloosobowej wszyscy uczestnicy otrzymuj\u0105 ten sam materia\u0142.",
              "Na pocz\u0105tku gra odczytuje bie\u017C\u0105ce zdanie, a nast\u0119pnie pierwsze s\u0142owo do wpisania.",
              "Wpisz je dok\u0142adnie, uwzgl\u0119dniaj\u0105c interpunkcj\u0119, i naci\u015Bnij Spacj\u0119, aby przej\u015B\u0107 dalej.",
              "Dop\u00F3ki nie zatwierdzisz s\u0142owa, mo\u017Cesz poprawia\u0107 je klawiszem Backspace. Po naci\u015Bni\u0119ciu Spacji gra ocenia wpisane s\u0142owo i przechodzi do nast\u0119pnego.",
              "Je\u015Bli pope\u0142nisz b\u0142\u0105d, us\u0142yszysz charakterystyczny d\u017Awi\u0119k i komunikat, ale rozgrywka b\u0119dzie kontynuowana.\nMo\u017Cesz skorzysta\u0107 z gotowych tekst\u00F3w dost\u0119pnych na li\u015Bcie w ustawieniach sto\u0142u, importowa\u0107 w\u0142asne pliki lub wklei\u0107 dowoln\u0105 tre\u015B\u0107.\nPo wybraniu tekstu w opisie sto\u0142u pojawi si\u0119 jego tytu\u0142 oraz liczba znak\u00F3w razem ze spacjami. Informacje te b\u0119d\u0105 r\u00F3wnie\u017C widoczne na widgecie, dzi\u0119ki czemu pozostali gracze mog\u0105 przed do\u0142\u0105czeniem oszacowa\u0107 d\u0142ugo\u015B\u0107 gry.",
              "Je\u017Celi chcesz u\u017Cy\u0107 w\u0142asnego materia\u0142u, wybierz Wklej tekst. Na ekranie ustawie\u0144 wpisz jego tytu\u0142, a nast\u0119pnie naci\u015Bnij Tab, aby przej\u015B\u0107 do pola tre\u015Bci.",
              "Importowane pliki musz\u0105 by\u0107 zapisane w kodowaniu UTF-8. Maksymalny rozmiar pliku lub wklejonego tekstu wynosi 1000 kB. Jako \u017Ce niekt\u00F3re znaki zajmuj\u0105 wi\u0119cej ni\u017C jeden bajt, jest to nieco mniej ni\u017C miion znak\u00F3w. Twoje teksty s\u0105 przechowywane lokalnie na komputerze. Je\u015Bli jednak wykorzystasz w\u0142asny tekst w grze wieloosobowej, przy rozpocz\u0119ciu rozgrywki zostanie on udost\u0119pniony uczestnikom przez serwer Eltena.\nDomy\u015Blnie Swobodne pisanie trwa do zako\u0144czenia ca\u0142ego tekstu. Je\u015Bli jednak wolisz kr\u00F3tsz\u0105 rozgrywk\u0119, mo\u017Cesz ustawi\u0107 limit czasu. Po jego up\u0142ywie runda si\u0119 zako\u0144czy, nawet je\u015Bli jeste\u015B w po\u0142owie s\u0142owa.\nJe\u015Bli grasz samodzielnie, mo\u017Cesz r\u00F3wnie\u017C wybra\u0107 pisanie bez tekstu \u017Ar\u00F3d\u0142owego. W takim przypadku zamiast przepisywa\u0107 gotowy materia\u0142, wpisujesz w\u0142asn\u0105 tre\u015B\u0107. Je\u017Celi nie ustawisz limitu czasu, mo\u017Cesz pisa\u0107 tak d\u0142ugo, jak chcesz. Aby zako\u0144czy\u0107 tak\u0105 sesj\u0119, wybierz Zako\u0144cz pisanie.\nPodczas samodzielnego przepisywania gotowego tekstu gra zapami\u0119tuje lokalnie Tw\u00F3j post\u0119p po zako\u0144czeniu lub opuszczeniu rozgrywki. Dzi\u0119ki temu mo\u017Cesz p\u00F3\u017Aniej kontynuowa\u0107 przepisywanie bez konieczno\u015Bci rozpoczynania tego samego tekstu od pocz\u0105tku. Je\u017Celi chcesz przepisa\u0107 go ponownie w ca\u0142o\u015Bci, wyzeruj post\u0119p w sekcji Lokalne teksty i post\u0119p."),
            rule_section(:main_7, "Losowe s\u0142owa",
              "W tym wariancie gra odczytuje kolejne losowo wybrane s\u0142owa. Twoim zadaniem jest poprawnie wpisa\u0107 ka\u017Cde z nich i zatwierdzi\u0107 je Spacj\u0105.",
              "W przeciwie\u0144stwie do Swobodnego pisania poprawno\u015B\u0107 jest sprawdzana podczas wpisywania poszczeg\u00F3lnych znak\u00F3w. Je\u015Bli naci\u015Bniesz niew\u0142a\u015Bciwy klawisz, pope\u0142nisz jeden b\u0142\u0105d, ale kursor nie przesunie si\u0119 dalej. Musisz wpisa\u0107 poprawny znak, aby kontynuowa\u0107.",
              "Backspace nie dzia\u0142a, poniewa\u017C b\u0142\u0119dne znaki nie s\u0105 dopisywane do poprawnie wpisanego pocz\u0105tku s\u0142owa.",
              "W rozgrywce wieloosobowej obowi\u0105zuje dodatkowo limit bezczynno\u015Bci wynosz\u0105cy pi\u0119\u0107 sekund.\nJe\u015Bli przez ten czas nie rozpoczniesz lub nie b\u0119dziesz kontynuowa\u0107 wpisywania, otrzymasz b\u0142\u0105d. Licznik dzia\u0142a r\u00F3wnie\u017C przed naci\u015Bni\u0119ciem pierwszego klawisza.",
              "Mo\u017Cesz wywo\u0142a\u0107 odpowiednim skr\u00F3tem odczytanie lub przeliterowanie s\u0142owa. Na czas wypowiedzi czytnika ekranu licznik zostanie zatrzymany, a po jej zako\u0144czeniu otrzymasz pe\u0142ne pi\u0119\u0107 sekund.",
              "W grze solo nie ma kary za bezczynno\u015B\u0107, wi\u0119c mo\u017Cesz \u0107wiczy\u0107 we w\u0142asnym tempie.\nW ustawieniach tego wariantu mo\u017Cesz zdecydowa\u0107, czy chcesz korzysta\u0107 ze zwyk\u0142ej klawiatury, brajla czy trybu mieszanego.",
              "W trybie mieszanym gra osobno dla ka\u017Cdego s\u0142owa losuje metod\u0119 jego wpisywania.",
              "Szczeg\u00F3\u0142owe informacje o obs\u0142udze brajla znajdziesz w dalszej cz\u0119\u015Bci tego rozdzia\u0142u."),
            rule_section(:main_9, "\u0141a\u0144cuch pami\u0119ciowy",
              "Ten wariant polega na zapami\u0119tywaniu coraz d\u0142u\u017Cszego ci\u0105gu s\u0142\u00F3w.",
              "Na pocz\u0105tku gra podaje jedno s\u0142owo, kt\u00F3re musisz wpisa\u0107. Nast\u0119pnie dodaje kolejne, ale odczytuje tylko nowy element.",
              "Twoim zadaniem jest za ka\u017Cdym razem odtworzy\u0107 ca\u0142y ci\u0105g od pocz\u0105tku, oddzielaj\u0105c poszczeg\u00F3lne s\u0142owa Spacj\u0105.",
              "Przyk\u0142adowo, je\u015Bli najpierw us\u0142yszysz \u201Ekot\u201D, a nast\u0119pnie \u201Eogr\u00F3d\u201D, musisz wpisa\u0107 oba s\u0142owa w odpowiedniej kolejno\u015Bci. Gdy pojawi si\u0119 trzecie s\u0142owo, wpisujesz ju\u017C wszystkie trzy.",
              "Z ka\u017Cd\u0105 kolejn\u0105 pr\u00F3b\u0105 zadanie staje si\u0119 trudniejsze, poniewa\u017C musisz pami\u0119ta\u0107 coraz wi\u0119cej element\u00F3w.",
              "Podobnie jak w Losowych s\u0142owach, b\u0142\u0119dny znak dodaje b\u0142\u0105d, ale nie przesuwa kursora i nie ma mo\u017Cliwo\u015Bci u\u017Cycia klawisza backspace. W tym trybie wyst\u0119puje analogiczna kara za bezczynno\u015B\u0107 oraz mo\u017Cliwo\u015B\u0107 pisania brajlem.",
              "Tryb mieszany w tym przypadku jest dla nieuleczalnych nerd\u00F3w, poniewa\u017C nale\u017Cy odtworzy\u0107 z pami\u0119ci zar\u00F3wno s\u0142owo, jak i spos\u00F3b, w jaki nale\u017Ca\u0142o je wpisa\u0107."),
            rule_section(:main_10, "Tryb przetrwania",
              "W Przetrwaniu Twoim zadaniem jest wpisywanie kolejnych s\u0142\u00F3w, zanim sko\u0144czy si\u0119 odtwarzana muzyka.",
              "Ka\u017Cde s\u0142owo ma w\u0142asny limit czasu, wyznaczany przez d\u0142ugo\u015B\u0107 nagrania.",
              "W ustawieniach sto\u0142u mo\u017Cesz wybra\u0107 jeden z trzech poziom\u00F3w trudno\u015Bci.",
              "- \u0141atwy - pocz\u0105tkowo oko\u0142o 16 sekund.\n- \u015Aredni - pocz\u0105tkowo oko\u0142o 10,67 sekundy.\n- Trudny - pocz\u0105tkowo oko\u0142o 6,64 sekundy.",
              "Po ka\u017Cdym poprawnie uko\u0144czonym s\u0142owie muzyka przyspiesza o 2,5 procent, a jej ton staje si\u0119 wy\u017Cszy.",
              "Oznacza to, \u017Ce im d\u0142u\u017Cej grasz bez b\u0142\u0119d\u00F3w, tym mniej czasu masz na wpisanie kolejnych s\u0142\u00F3w.\nW tym wariancie nie zatwierdzasz s\u0142\u00F3w Spacj\u0105. Gdy wpiszesz ostatni poprawny znak, gra automatycznie przechodzi do nast\u0119pnego s\u0142owa.",
              "Je\u017Celi naci\u015Bniesz niew\u0142a\u015Bciwy klawisz, otrzymasz b\u0142\u0105d, ale zachowasz poprawnie wpisany pocz\u0105tek s\u0142owa.",
              "Je\u015Bli muzyka sko\u0144czy si\u0119 przed uko\u0144czeniem s\u0142owa, gra doliczy b\u0142\u0105d i rozpocznie kolejne s\u0142owo. W takim przypadku muzyka nie zostanie przyspieszona.\nPami\u0119taj, \u017Ce odczytywanie, literowanie oraz wyciszenie muzyki nie zatrzymuj\u0105 up\u0142ywu czasu.",
              "Nie obowi\u0105zuje tutaj dodatkowy licznik bezczynno\u015Bci, poniewa\u017C czas na wpisanie ka\u017Cdego s\u0142owa wyznacza sama muzyka.",
              "Tutaj r\u00F3wnie\u017C mo\u017Cesz korzysta\u0107 ze zwyk\u0142ej klawiatury, brajla lub trybu mieszanego."),
            rule_section(:main_11, "Pisanie brajlem",
              "Zamiast wpisywa\u0107 znaki pojedynczymi klawiszami, mo\u017Cesz korzysta\u0107 z uk\u0142adu imituj\u0105cego klawiatur\u0119 brajlowsk\u0105.",
              "Punkty brajlowskie odpowiadaj\u0105 nast\u0119puj\u0105cym klawiszom.",
              "- Punkty 1, 2 i 3 - F, D, S.\n- Punkty 4, 5 i 6 - J, K, L.\n- Punkt 7 - A.\n- Punkt 8 - \u015Brednik.",
              "Aby wpisa\u0107 znak brajlowski, naci\u015Bnij jednocze\u015Bnie odpowiednie klawisze, a nast\u0119pnie zwolnij je.\nW Ustawieniach manii pisania mo\u017Cesz wybra\u0107 r\u00F3\u017Cne tablice dla swojego j\u0119zyka albo lokaln\u0105 tablic\u0119 Liblouis, wskazywan\u0105 jako plik ctb, utb, tbl lub uti."),
            rule_section(:main_12, "Ustawienia manii pisania",
              "Naci\u015Bnij Ctrl+P, aby otworzy\u0107 Ustawienia manii pisania.",
              "Znajdziesz tam opcje dotycz\u0105ce brajla, echa pisania, powiadomie\u0144 o b\u0142\u0119dach oraz g\u0142o\u015Bno\u015Bci muzyki.",
              "Echo pisania okre\u015Bla, co gra odczytuje podczas wpisywania tekstu.",
              "Mo\u017Cesz pozostawi\u0107 zachowanie zgodne z ustawieniami Eltena albo osobno wybra\u0107 odczytywanie znak\u00F3w, s\u0142\u00F3w, znak\u00F3w i s\u0142\u00F3w lub ca\u0142kowicie wy\u0142\u0105czy\u0107 echo.",
              "Zmiany te dotycz\u0105 wy\u0142\u0105cznie pola pisania podczas rozgrywki.\nKolejna rzecz do ustawienia to spos\u00F3b, w jaki gra b\u0119dzie informowa\u0107 Ci\u0119 o pope\u0142nionych b\u0142\u0119dach.",
              "Powiadomienia g\u0142osowe i d\u017Awi\u0119kowe s\u0105 niezale\u017Cne. Mo\u017Cesz korzysta\u0107 z obu metod jednocze\u015Bnie, wybra\u0107 tylko jedn\u0105 albo ca\u0142kowicie wy\u0142\u0105czy\u0107 powiadomienia.\nOstatnia opcja to suwak g\u0142o\u015Bno\u015Bci muzyki regulowany od 0 do 100 procent."),
            rule_section(:main_13, "Rundy i mecze wieloosobowe",
              "W wariantach Losowe s\u0142owa, \u0141a\u0144cuch pami\u0119ciowy i Przetrwanie mo\u017Cesz wybra\u0107 ustalon\u0105 liczb\u0119 rund albo parti\u0119 trwaj\u0105c\u0105 a\u017C do zako\u0144czenia jej przez gospodarza.",
              "W ka\u017Cdej rundzie gracze zdobywaj\u0105 wyniki zgodnie z zasadami wybranego wariantu.",
              "Je\u015Bli zdecydujesz si\u0119 na mecz wielorundowy, ostateczne zwyci\u0119stwo zale\u017Cy od liczby wygranych rund.",
              "Pozwala to zorganizowa\u0107 zar\u00F3wno kr\u00F3tk\u0105 rozgrywk\u0119, jak i d\u0142u\u017Cszy turniej, w kt\u00F3rym pojedyncze niepowodzenie nie musi przes\u0105dza\u0107 o ca\u0142ym wyniku."),
            rule_section(:touch_0, "Pisanie bezwzrokowe",
              "Pisanie bezwzrokowe polega na wpisywaniu tekstu bez patrzenia na klawiatur\u0119. Regularne \u0107wiczenia ucz\u0105 automatycznego odnajdywania klawiszy, co mo\u017Ce poprawi\u0107 szybko\u015B\u0107, dok\u0142adno\u015B\u0107 i wygod\u0119 pisania. To cenna umiej\u0119tno\u015B\u0107 w wielu zawodach, w kt\u00F3rych szybko\u015B\u0107 pisania wp\u0142ywa na wydajno\u015B\u0107, mi\u0119dzy innymi u programist\u00F3w, dziennikarzy i pisarzy."),
            rule_section(:touch_1, "Podstawowe zasady",
              "U\u0142\u00F3\u017C palce lewej d\u0142oni na klawiszach A, S, D i F, a prawej na J, K, L i \u015Bredniku (;). Kciuki oprzyj na Spacji.",
              "Na klawiszach F i J znajduj\u0105 si\u0119 ma\u0142e wypustki, kt\u00F3re pomagaj\u0105 odnale\u017A\u0107 pozycj\u0119 wyj\u015Bciow\u0105 obu d\u0142oni bez patrzenia.",
              "To pozycja podstawowa. Pozosta\u0142e znaki wpisujesz, przesuwaj\u0105c palce na s\u0105siednie klawisze. Na przyk\u0142ad, aby wpisa\u0107 z, przesu\u0144 lewy ma\u0142y palec z a w d\u00F3\u0142. Aby wpisa\u0107 q, przesu\u0144 ten sam palec w g\u00F3r\u0119. Aby wpisa\u0107 y, przesu\u0144 prawy palec wskazuj\u0105cy z j uko\u015Bnie w g\u00F3r\u0119 i w lewo."),
            rule_section(:touch_2, "Pi\u0119\u0107 z\u0142otych zasad pisania bezwzrokowego",
              "1. U\u017Cywaj wszystkich palc\u00F3w. Ka\u017Cdemu przypisane s\u0105 okre\u015Blone klawisze. Staraj si\u0119 przestrzega\u0107 tego podzia\u0142u podczas nauki.",
              "2. Wracaj do pozycji podstawowej. Po naci\u015Bni\u0119ciu klawisza od\u0142\u00F3\u017C palec na jego miejsce. Na przyk\u0142ad po wpisaniu r wr\u00F3\u0107 lewym palcem wskazuj\u0105cym na f.",
              "3. Naciskaj Spacj\u0119 kciukiem. Wielkie litery wpisuj z Shiftem po przeciwnej stronie klawiatury. Na przyk\u0142ad do A u\u017Cyj prawego Shifta, a do K lewego.",
              "4. Rozlu\u017Aniaj d\u0142onie. Wykonuj lekkie, naturalne ruchy i trzymaj nadgarstki mo\u017Cliwie prosto, w wygodnej pozycji.",
              "5. Nie spiesz si\u0119. Najpierw skup si\u0119 na dok\u0142adno\u015Bci. Szybko\u015B\u0107 przyjdzie z praktyk\u0105."),
            rule_section(:touch_3, "Jak skutecznie \u0107wiczy\u0107",
              "\u0106wicz regularnie. Zacznij od kr\u00F3tkich sesji trwaj\u0105cych oko\u0142o 10\u201315 minut.",
              "Skup si\u0119 na dok\u0142adno\u015Bci. Ogranicz liczb\u0119 b\u0142\u0119d\u00F3w, zanim zaczniesz stopniowo zwi\u0119ksza\u0107 tempo.",
              "Powtarzaj trudne po\u0142\u0105czenia. Je\u015Bli jaki\u015B klawisz lub s\u0142owo sprawia Ci trudno\u015B\u0107, po\u015Bwi\u0119\u0107 mu wi\u0119cej czasu.",
              "\u015Aled\u017A post\u0119py. Por\u00F3wnuj wyniki z kolejnych trening\u00F3w, pami\u0119taj\u0105c, \u017Ce szybko\u015B\u0107 nie jest najwa\u017Cniejsza.",
              "R\u00F3b przerwy. Je\u015Bli tracisz koncentracj\u0119 lub czujesz dyskomfort w d\u0142oniach, przerwij \u0107wiczenie i odpocznij."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "- Ctrl+L: Literuj bie\u017C\u0105ce s\u0142owo.",
              "- Ctrl+O: Odczytaj bie\u017C\u0105ce s\u0142owo.",
              "- Ctrl+;: Odczytaj reszt\u0119 s\u0142owa (niedost\u0119pne w \u0141a\u0144cuchu pami\u0119ciowym).",
              "- Ctrl+Shift+;: Odczytaj reszt\u0119 zdania (Swobodne pisanie).",
              "- Alt+S: Odczytaj post\u0119p.",
              "- Ctrl+P: Otw\u00F3rz ustawienia pisania.",
              "- Space: Zatwierd\u017A s\u0142owo (poza Przetrwaniem).",
              "- Backspace: Popraw bie\u017C\u0105ce s\u0142owo (Swobodne pisanie).",
              "- Ctrl+S: Zapisz i zamknij st\u00F3\u0142.",
              "- F1: Pomoc kontekstowa.",
              "- Ctrl+F1: Pomoc gry.",
              "- Escape: Opu\u015B\u0107 st\u00F3\u0142.")
          ]
        when "ru"
          [
            rule_section(:main_0, "\u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u044F",
              "\u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u044F - \u0438\u0433\u0440\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043C\u043E\u0436\u043D\u043E \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u043F\u0435\u0447\u0430\u0442\u0438, \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C \u0438 \u043F\u0430\u043C\u044F\u0442\u044C. \u0418\u0433\u0440\u0430\u0439 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E, \u0441\u043E\u0440\u0435\u0432\u043D\u0443\u0439\u0441\u044F \u0441 \u0434\u0440\u0443\u0437\u044C\u044F\u043C\u0438 \u0438\u043B\u0438 \u043F\u0440\u043E\u0441\u0442\u043E \u0441\u043B\u0435\u0434\u0438 \u0437\u0430 \u0441\u0432\u043E\u0438\u043C\u0438 \u0443\u0441\u043F\u0435\u0445\u0430\u043C\u0438.",
              "\u041D\u0430 \u0432\u044B\u0431\u043E\u0440 \u0435\u0441\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0435\u0436\u0438\u043C\u043E\u0432, \u043E\u0442 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u044F \u0440\u0430\u0441\u0441\u043A\u0430\u0437\u043E\u0432 \u0434\u043E \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0439, \u0433\u0434\u0435 \u0432\u0430\u0436\u043D\u0430 \u043A\u0430\u0436\u0434\u0430\u044F \u0441\u0435\u043A\u0443\u043D\u0434\u0430. \u0417\u0434\u0435\u0441\u044C \u0442\u044B \u0443\u0437\u043D\u0430\u0435\u0448\u044C, \u043A\u0430\u043A \u043D\u0430\u0447\u0430\u0442\u044C \u0438\u0433\u0440\u0443, \u043A\u0430\u043A \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0442 \u0440\u0430\u0437\u043D\u044B\u0435 \u0440\u0435\u0436\u0438\u043C\u044B \u0438 \u043D\u0430 \u0447\u0442\u043E \u043E\u0431\u0440\u0430\u0449\u0430\u0442\u044C \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435 \u043F\u0440\u0438 \u043D\u0430\u0431\u043E\u0440\u0435 \u0442\u0435\u043A\u0441\u0442\u0430."),
            rule_section(:main_1, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0422\u0432\u043E\u044F \u0437\u0430\u0434\u0430\u0447\u0430 - \u043F\u0435\u0447\u0430\u0442\u0430\u0442\u044C \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u0431\u044B\u0441\u0442\u0440\u0435\u0435 \u0438 \u0434\u043E\u043F\u0443\u0441\u043A\u0430\u0442\u044C \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u043C\u0435\u043D\u044C\u0448\u0435 \u043E\u0448\u0438\u0431\u043E\u043A. \u0412 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u0438 \u043E\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0430 \u0442\u0435\u0431\u0435 \u043F\u0440\u0435\u0434\u0441\u0442\u043E\u0438\u0442 \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u0442\u044C \u0433\u043E\u0442\u043E\u0432\u044B\u0439 \u0442\u0435\u043A\u0441\u0442, \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430, \u0437\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0442\u044C \u0432\u0441\u0451 \u0431\u043E\u043B\u0435\u0435 \u0434\u043B\u0438\u043D\u043D\u044B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0441\u043B\u043E\u0432 \u0438\u043B\u0438 \u0441\u043E\u0440\u0435\u0432\u043D\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0435\u043C.\n\u041C\u043E\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C \u043E\u0434\u043D\u043E\u043C\u0443 \u0438\u043B\u0438 \u0432 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438 \u0435\u0449\u0451 \u0441\u0435\u043C\u0438 \u0447\u0435\u043B\u043E\u0432\u0435\u043A. \u0412 \u043C\u043D\u043E\u0433\u043E\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0439 \u0438\u0433\u0440\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438 \u0441\u043E\u0440\u0435\u0432\u043D\u0443\u044E\u0442\u0441\u044F \u0437\u0430 \u043B\u0443\u0447\u0448\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u041F\u043E\u0431\u0435\u0434\u0430 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043A\u0430\u043A \u043E\u0442 \u0441\u0440\u0435\u0434\u043D\u0435\u0433\u043E \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0441\u043B\u043E\u0432 \u0432 \u043C\u0438\u043D\u0443\u0442\u0443, \u0442\u0430\u043A \u0438 \u043E\u0442 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u0438, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0432\u043B\u0438\u044F\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u0434\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u044B\u0445 \u043E\u0448\u0438\u0431\u043E\u043A.",
              "\u041E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u0440\u0435\u0436\u0438\u043C - \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0432\u0441\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u044E\u0442 \u043E\u0434\u0438\u043D \u0438 \u0442\u043E\u0442 \u0436\u0435 \u0442\u0435\u043A\u0441\u0442. \u0421\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u0432\u0430\u0436\u043D\u0430, \u043D\u043E \u043E\u0448\u0438\u0431\u043A\u0438 \u0441\u043D\u0438\u0436\u0430\u044E\u0442 \u0438\u0442\u043E\u0433\u043E\u0432\u0443\u044E \u043E\u0446\u0435\u043D\u043A\u0443. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u0431\u043E\u043B\u0435\u0435 \u0442\u043E\u0447\u043D\u044B\u0439 \u0438\u0433\u0440\u043E\u043A \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u044C, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u043F\u0435\u0447\u0430\u0442\u0430\u0435\u0442 \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u0435\u0435.",
              "\u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0440\u0435\u0436\u0438\u043C\u044B \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u0435 \u043D\u0430\u0432\u044B\u043A\u0438. \u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0442 \u043D\u0430\u0432\u044B\u043A\u0438 \u043D\u0430\u0431\u043E\u0440\u0430 \u0442\u0435\u043A\u0441\u0442\u0430, \u0426\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0430\u043C\u044F\u0442\u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0437\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0441\u043B\u043E\u0432, \u0430 \u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0435 \u0438\u0441\u043F\u044B\u0442\u044B\u0432\u0430\u0435\u0442 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u0440\u0435\u0430\u043A\u0446\u0438\u0438."),
            rule_section(:main_2, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430",
              "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u043E\u0437\u0434\u0430\u0439 \u0438\u0433\u0440\u043E\u0432\u043E\u0439 \u0441\u0442\u043E\u043B. \u0415\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u0438\u0442\u044C \u0434\u043B\u044F \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043A\u0438 \u0438\u043B\u0438 \u043F\u0440\u0438\u0433\u043B\u0430\u0441\u0438\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "\u0421\u0430\u043C\u043E\u0435 \u0432\u0430\u0436\u043D\u043E\u0435 - \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0438\u0433\u0440\u043E\u0432\u043E\u0439 \u0440\u0435\u0436\u0438\u043C. \u041A\u0430\u0436\u0434\u044B\u0439 \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0440\u0435\u0436\u0438\u043C\u043E\u0432 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0441\u0432\u043E\u0451 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435 \u0438 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043D\u0430\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0438\u0433\u0440\u0443 \u043F\u043E\u0434 \u0441\u0435\u0431\u044F.",
              "\u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 \u0437\u0430\u043A\u043B\u044E\u0447\u0430\u0435\u0442\u0441\u044F \u0432 \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430. \u041C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0433\u043E\u0442\u043E\u0432\u044B\u0435 \u0440\u0430\u0441\u0441\u043A\u0430\u0437\u044B, \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0444\u0430\u0439\u043B\u044B \u0438\u043B\u0438 \u0432\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442. \u0412 \u044D\u0442\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0442\u0430\u043A\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0442\u044C \u0432\u0440\u0435\u043C\u044F \u043D\u0430\u0431\u043E\u0440\u0430, \u0430 \u043F\u0440\u0438 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u043E\u0442\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u043E\u0442 \u043E\u0431\u0440\u0430\u0437\u0446\u0430 \u0438 \u043F\u0438\u0441\u0430\u0442\u044C \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442.",
              "\u0412 \u0440\u0435\u0436\u0438\u043C\u0435 \u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u043D\u0443\u0436\u043D\u043E \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u0441\u043B\u043E\u0432\u0430, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0438\u0433\u0440\u0430. \u041C\u043E\u0436\u043D\u043E \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u043E\u0439, \u0432\u0432\u043E\u0434\u043E\u043C \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E \u0438\u043B\u0438 \u0441\u043C\u0435\u0448\u0430\u043D\u043D\u044B\u043C \u0440\u0435\u0436\u0438\u043C\u043E\u043C, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0441\u043F\u043E\u0441\u043E\u0431 \u0432\u0432\u043E\u0434\u0430 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043E\u0442 \u0441\u043B\u043E\u0432\u0430 \u043A \u0441\u043B\u043E\u0432\u0443.",
              "\u0426\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0430\u043C\u044F\u0442\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0445\u043E\u0440\u043E\u0448\u043E \u0442\u044B \u0437\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0448\u044C \u0443\u0434\u043B\u0438\u043D\u044F\u044E\u0449\u0443\u044E\u0441\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0441\u043B\u043E\u0432. \u041F\u0440\u0438 \u043A\u0430\u0436\u0434\u043E\u0439 \u043D\u043E\u0432\u043E\u0439 \u043F\u043E\u043F\u044B\u0442\u043A\u0435 \u043D\u0443\u0436\u043D\u043E \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0441\u0442\u0438 \u0432\u0441\u0435 \u0441\u043B\u043E\u0432\u0430 \u0441 \u0441\u0430\u043C\u043E\u0433\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u0432 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u043C \u043F\u043E\u0440\u044F\u0434\u043A\u0435.",
              "\u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u0435\u0442 \u043D\u0430\u0431\u043E\u0440 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0445 \u0441\u043B\u043E\u0432 \u0441 \u0433\u043E\u043D\u043A\u043E\u0439 \u043D\u0430 \u0432\u0440\u0435\u043C\u044F. \u0422\u044B \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u0443\u0440\u043E\u0432\u0435\u043D\u044C \u0441\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u0438, \u043E\u0442 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u0442\u0435\u043C\u043F \u0438\u0433\u0440\u044B.",
              "\u041F\u043E\u0441\u043B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0447\u0430\u0442\u044C \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043A\u0443 \u0438\u043B\u0438 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C \u0441\u0442\u043E\u043B, \u0447\u0442\u043E\u0431\u044B \u043A \u043D\u0435\u043C\u0443 \u043F\u0440\u0438\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u043B\u0438\u0441\u044C \u0434\u0440\u0443\u0433\u0438\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438. \u0414\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u044B\u0435 \u0444\u0443\u043D\u043A\u0446\u0438\u0438 PowerGames, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043F\u0440\u0438\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u044F, \u043D\u0430\u0431\u043B\u044E\u0434\u0435\u043D\u0438\u0435 \u0437\u0430 \u0438\u0433\u0440\u043E\u0439, \u0447\u0430\u0442 \u0438 \u0438\u0441\u0442\u043E\u0440\u0438\u044E \u043F\u0430\u0440\u0442\u0438\u0439.",
              "\u041F\u043E\u0434\u0440\u043E\u0431\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0430 \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043E\u043F\u0438\u0441\u0430\u043D\u044B \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \u00AB\u0420\u0435\u0436\u0438\u043C\u044B \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u0433\u0440\u043E\u0432\u043E\u0433\u043E \u0441\u0442\u043E\u043B\u0430\u00BB."),
            rule_section(:main_3, "\u041A\u0430\u043A \u0438\u0433\u0440\u0430\u0442\u044C",
              "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043D\u043E\u0432\u043E\u0433\u043E \u0440\u0430\u0443\u043D\u0434\u0430 \u0444\u043E\u043A\u0443\u0441 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u0432 \u043F\u043E\u043B\u0435 \u0432\u0432\u043E\u0434\u0430. \u0415\u0441\u043B\u0438 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0438\u0433\u0440\u044B \u0442\u044B \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0448\u044C \u043A \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u0443 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430, \u0432\u0435\u0440\u043D\u0438 \u0444\u043E\u043A\u0443\u0441 \u0432 \u043F\u043E\u043B\u0435 \u0432\u0432\u043E\u0434\u0430, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C.",
              "\u0418\u0433\u0440\u0430 \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u043B\u043E\u0432\u0430, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C. \u0412 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u0438 \u043E\u0442 \u0440\u0435\u0436\u0438\u043C\u0430 \u043E\u043D\u0430 \u0442\u0430\u043A\u0436\u0435 \u043C\u043E\u0436\u0435\u0442 \u0447\u0438\u0442\u0430\u0442\u044C \u0446\u0435\u043B\u044B\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438\u043B\u0438 \u043F\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u0441\u043F\u043E\u043C\u043D\u0438\u0442\u044C \u0441\u043B\u043E\u0432\u0430, \u0443\u0441\u043B\u044B\u0448\u0430\u043D\u043D\u044B\u0435 \u0440\u0430\u043D\u0435\u0435.",
              "\u041E\u0431\u044B\u0447\u043D\u043E \u043F\u043E\u0441\u043B\u0435 \u043D\u0430\u0431\u043E\u0440\u0430 \u0441\u043B\u043E\u0432\u0430 \u0435\u0433\u043E \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 \u041F\u0440\u043E\u0431\u0435\u043B. \u0418\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 - \u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0435, \u0433\u0434\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
              "\u0420\u0430\u0431\u043E\u0442\u0430 \u0441 \u043E\u0448\u0438\u0431\u043A\u0430\u043C\u0438 \u0442\u043E\u0436\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0440\u0435\u0436\u0438\u043C\u0430. \u0412 \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u043C \u043D\u0430\u0431\u043E\u0440\u0435 \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0435\u0435 \u0441\u043B\u043E\u0432\u043E \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Backspace, \u043F\u043E\u043A\u0430 \u043E\u043D\u043E \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. \u0412 \u0434\u0440\u0443\u0433\u0438\u0445 \u0440\u0435\u0436\u0438\u043C\u0430\u0445 \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u043A\u0430\u0436\u0434\u044B\u0439 \u0441\u0438\u043C\u0432\u043E\u043B \u0441\u0440\u0430\u0437\u0443. \u0415\u0441\u043B\u0438 \u043D\u0430\u0436\u0430\u0442\u044C \u043D\u0435\u0432\u0435\u0440\u043D\u0443\u044E \u043A\u043B\u0430\u0432\u0438\u0448\u0443, \u0438\u0433\u0440\u0430 \u043D\u0435 \u043F\u0440\u043E\u0434\u0432\u0438\u043D\u0435\u0442\u0441\u044F \u0434\u0430\u043B\u044C\u0448\u0435, \u0430 \u0431\u0443\u0434\u0435\u0442 \u0436\u0434\u0430\u0442\u044C \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u0441\u0438\u043C\u0432\u043E\u043B.",
              "\u0412\u043E \u0432\u0440\u0435\u043C\u044F \u0438\u0433\u0440\u044B \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0441\u043B\u043E\u0432\u043E \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E (Ctrl+O), \u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u043F\u0440\u043E\u0438\u0437\u043D\u0435\u0441\u0442\u0438 \u0435\u0433\u043E \u043F\u043E \u0431\u0443\u043A\u0432\u0430\u043C (Ctrl+L) \u0438\u043B\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043A\u043B\u0430\u0432\u0438\u0448 \u0434\u043B\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u0435\u043D\u0438\u044F \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u043E\u0432 \u0442\u0435\u043A\u0441\u0442\u0430. \u041F\u043E\u043B\u043D\u044B\u0439 \u0441\u043F\u0438\u0441\u043E\u043A \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0435\u0439 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0433\u043E\u0440\u044F\u0447\u0438\u0445 \u043A\u043B\u0430\u0432\u0438\u0448.",
              "\u041F\u0440\u0438 \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u0438 \u0442\u0435\u043A\u0441\u0442\u043E\u0432 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0441\u043E\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0431\u0443\u043A\u0432 \u0438\u043B\u0438 \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u044C \u0432\u0441\u0435 \u0442\u0438\u043F\u043E\u0433\u0440\u0430\u0444\u0441\u043A\u0438\u0435 \u0441\u0438\u043C\u0432\u043E\u043B\u044B \u0432 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u0438. \u0418\u0433\u0440\u0430 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u0431\u043E\u043B\u0435\u0435 \u043F\u0440\u043E\u0441\u0442\u044B\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B, \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043D\u0430 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0435. \u042D\u0442\u043E \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0440\u0430\u0437\u043B\u0438\u0447\u043D\u044B\u043C \u0432\u0438\u0434\u0430\u043C \u043A\u0430\u0432\u044B\u0447\u0435\u043A, \u043F\u0440\u043E\u0431\u0435\u043B\u043E\u0432, \u0442\u0438\u0440\u0435 \u0438 \u043C\u043D\u043E\u0433\u043E\u0442\u043E\u0447\u0438\u044E.\n\u0415\u0441\u043B\u0438 \u0432 \u0442\u0435\u043A\u0441\u0442\u0435 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u044E\u0442\u0441\u044F \u0447\u0438\u0441\u043B\u0430, \u0438\u0433\u0440\u0430 \u0441\u043E\u043E\u0431\u0449\u0438\u0442, \u0447\u0442\u043E \u0438\u0445 \u043D\u0443\u0436\u043D\u043E \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u0446\u0438\u0444\u0440\u0430\u043C\u0438.",
              "\u041F\u0440\u0438 \u0438\u043C\u043F\u043E\u0440\u0442\u0435 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430 \u0442\u044B \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0438\u0448\u044C \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u043E \u043D\u0435\u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043C\u044B\u0445 \u0441\u0438\u043C\u0432\u043E\u043B\u0430\u0445, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u044C."),
            rule_section(:main_4, "\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u0438\u0433\u0440\u044B",
              "\u0421\u043F\u043E\u0441\u043E\u0431 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0430.",
              "\u0412 \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u043C \u043D\u0430\u0431\u043E\u0440\u0435 \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u044F \u0432\u0441\u0435\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430, \u0438\u0441\u0442\u0435\u0447\u0435\u043D\u0438\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u0438\u043B\u0438 \u0432\u044B\u0431\u043E\u0440\u0430 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u00AB\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u043D\u0430\u0431\u043E\u0440\u00BB.",
              "\u0412 \u0440\u0435\u0436\u0438\u043C\u0430\u0445 \u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430, \u0426\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0430\u043C\u044F\u0442\u0438 \u0438 \u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0435 \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u044F\u0442\u0438 \u043E\u0448\u0438\u0431\u043E\u043A. \u0415\u0433\u043E \u0442\u0430\u043A\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0432\u0440\u0443\u0447\u043D\u0443\u044E.",
              "\u0412 \u043C\u043D\u043E\u0433\u043E\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0439 \u0438\u0433\u0440\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u043F\u043E\u044F\u0432\u044F\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438 \u0437\u0430\u043A\u043E\u043D\u0447\u0430\u0442. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0438\u0433\u0440\u043E\u043A \u0441 \u043D\u0430\u0438\u0432\u044B\u0441\u0448\u0435\u0439 \u043E\u0446\u0435\u043D\u043A\u043E\u0439. \u0415\u0441\u043B\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u043D\u0430\u0431\u0440\u0430\u043B\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043E\u0447\u043A\u043E\u0432, \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0438\u0447\u044C\u044F.",
              "\u0412 \u043C\u0430\u0442\u0447\u0435 \u0438\u0437 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u0438\u0442\u043E\u0433\u043E\u0432\u0443\u044E \u043F\u043E\u0431\u0435\u0434\u0443 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432.",
              "\u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u044F \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442 \u0438 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u043D\u0430\u0431\u043E\u0440\u0430, \u0438 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u043E\u0446\u0435\u043D\u043A\u0430 - \u044D\u0442\u043E \u043D\u0435 \u043F\u0440\u043E\u0441\u0442\u043E \u0447\u0438\u0441\u043B\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0441\u043B\u043E\u0432.",
              "\u0412 \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u043C \u043D\u0430\u0431\u043E\u0440\u0435 \u043E\u0434\u0438\u043D \u0438\u0437 \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u0435\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430 - WPM, \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0441\u043B\u043E\u0432 \u0432 \u043C\u0438\u043D\u0443\u0442\u0443. \u0418\u0433\u0440\u0430 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0432\u0440\u0435\u043C\u044F, \u0437\u0430\u0442\u0440\u0430\u0447\u0435\u043D\u043D\u043E\u0435 \u043D\u0430 \u0438\u0445 \u0432\u0432\u043E\u0434, \u043D\u043E \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0432\u0440\u0435\u043C\u044F \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0438\u0432\u0430\u043D\u0438\u044F \u0434\u043E \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u043F\u0435\u0440\u0432\u043E\u0439 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u043E\u0447\u0435\u0440\u0435\u0434\u043D\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0441\u043B\u043E\u0432\u043E \u0438 \u0443\u0431\u0435\u0434\u0438\u0442\u044C\u0441\u044F, \u0447\u0442\u043E \u0438\u043C\u0435\u043D\u043D\u043E \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u043F\u0438\u0441\u0430\u0442\u044C.",
              "\u0412 \u0440\u0435\u0436\u0438\u043C\u0430\u0445 \u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430, \u0426\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0430\u043C\u044F\u0442\u0438 \u0438 \u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0435 \u043E\u0441\u043D\u043E\u0432\u043E\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430 \u0441\u043B\u0443\u0436\u0438\u0442 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0441\u043B\u043E\u0432.",
              "\u041D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u0440\u0435\u0436\u0438\u043C\u0430 \u0438\u0433\u0440\u0430 \u0442\u0430\u043A\u0436\u0435 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u043A\u043E\u044D\u0444\u0444\u0438\u0446\u0438\u0435\u043D\u0442 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u0438. \u041E\u043D \u0440\u0430\u0432\u0435\u043D \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0443 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0445 \u0441\u043B\u043E\u0432, \u0434\u0435\u043B\u0451\u043D\u043D\u043E\u043C\u0443 \u043D\u0430 \u0441\u0443\u043C\u043C\u0443 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0445 \u0441\u043B\u043E\u0432 \u0438 \u043E\u0448\u0438\u0431\u043E\u043A.",
              "\u0417\u0430\u0442\u0435\u043C \u0431\u0430\u0437\u043E\u0432\u044B\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0434\u0432\u0430\u0436\u0434\u044B \u0443\u043C\u043D\u043E\u0436\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u044D\u0442\u043E\u0442 \u043A\u043E\u044D\u0444\u0444\u0438\u0446\u0438\u0435\u043D\u0442.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0435\u0441\u043B\u0438 \u0442\u044B \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0435\u0440\u0451\u0448\u044C 20 \u0441\u043B\u043E\u0432 \u0438 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u0448\u044C 4 \u043E\u0448\u0438\u0431\u043A\u0438, \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u043E\u0446\u0435\u043D\u043A\u0430 \u0441\u043E\u0441\u0442\u0430\u0432\u0438\u0442 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E 13,89 \u0431\u0430\u043B\u043B\u0430.",
              "\u0418\u0433\u0440\u043E\u043A, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043D\u0430\u0431\u0435\u0440\u0451\u0442 17 \u0441\u043B\u043E\u0432 \u0431\u0435\u0437 \u0435\u0434\u0438\u043D\u043E\u0439 \u043E\u0448\u0438\u0431\u043A\u0438, \u043F\u043E\u043B\u0443\u0447\u0438\u0442 17 \u0431\u0430\u043B\u043B\u043E\u0432 \u0438 \u043F\u043E\u0431\u0435\u0434\u0438\u0442.\n\u041A\u0430\u043A \u0432\u0438\u0434\u0438\u0448\u044C, \u0441\u0442\u0440\u0435\u043C\u0438\u0442\u044C\u0441\u044F \u043F\u0435\u0447\u0430\u0442\u0430\u0442\u044C \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u0431\u044B\u0441\u0442\u0440\u0435\u0435 \u043D\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 \u0432\u044B\u0433\u043E\u0434\u043D\u043E. \u0418\u043D\u043E\u0433\u0434\u0430 \u043B\u0443\u0447\u0448\u0435 \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u0441\u043D\u0438\u0437\u0438\u0442\u044C \u0442\u0435\u043C\u043F, \u0437\u0430\u0442\u043E \u043F\u0438\u0441\u0430\u0442\u044C \u0442\u043E\u0447\u043D\u0435\u0435.\n\u0412 \u0438\u0442\u043E\u0433\u043E\u0432\u043E\u0439 \u0441\u0432\u043E\u0434\u043A\u0435 \u043E\u0442\u043E\u0431\u0440\u0430\u0436\u0430\u044E\u0442\u0441\u044F \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043E\u0446\u0435\u043D\u043A\u0430 \u0438 \u043F\u0440\u043E\u0446\u0435\u043D\u0442 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u0438."),
            rule_section(:main_5, "\u0420\u0435\u0436\u0438\u043C\u044B \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u0433\u0440\u043E\u0432\u043E\u0433\u043E \u0441\u0442\u043E\u043B\u0430",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u0440\u0435\u0436\u0438\u043C \u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u0438 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043F\u043E \u0441\u0432\u043E\u0438\u043C \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C. \u041E\u0442\u043B\u0438\u0447\u0430\u0435\u0442\u0441\u044F \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0430\u043C\u043E \u0437\u0430\u0434\u0430\u043D\u0438\u0435, \u043D\u043E \u0438 \u0441\u043F\u043E\u0441\u043E\u0431\u044B \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u043E\u0448\u0438\u0431\u043E\u043A, \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \u0441\u043B\u043E\u0432 \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438."),
            rule_section(:main_6, "\u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440",
              "\u0412 \u044D\u0442\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0442\u044B \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u0435\u0448\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442 \u0441\u043B\u043E\u0432\u043E \u0437\u0430 \u0441\u043B\u043E\u0432\u043E\u043C, \u043E\u0431\u044B\u0447\u043D\u044B\u043C \u0441\u043F\u043E\u0441\u043E\u0431\u043E\u043C \u0438\u043B\u0438 \u0441 \u0438\u043C\u0438\u0442\u0430\u0446\u0438\u0435\u0439 \u0431\u0440\u0430\u0439\u043B\u0435\u0432\u0441\u043A\u043E\u0439 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044B. \u0412 \u043C\u043D\u043E\u0433\u043E\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0439 \u0438\u0433\u0440\u0435 \u0432\u0441\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043E\u0434\u0438\u043D \u0438 \u0442\u043E\u0442 \u0436\u0435 \u0442\u0435\u043A\u0441\u0442.",
              "\u0412\u043D\u0430\u0447\u0430\u043B\u0435 \u0438\u0433\u0440\u0430 \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0435\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435, \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C.",
              "\u0412\u0432\u0435\u0434\u0438 \u0441\u043B\u043E\u0432\u043E \u0442\u043E\u0447\u043D\u043E, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0437\u043D\u0430\u043A\u0438 \u043F\u0440\u0435\u043F\u0438\u043D\u0430\u043D\u0438\u044F, \u0438 \u043D\u0430\u0436\u043C\u0438 \u041F\u0440\u043E\u0431\u0435\u043B, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C.",
              "\u041F\u043E\u043A\u0430 \u0441\u043B\u043E\u0432\u043E \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E, \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Backspace. \u041F\u043E\u0441\u043B\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u041F\u0440\u043E\u0431\u0435\u043B\u0430 \u0438\u0433\u0440\u0430 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442 \u0432\u0432\u0435\u0434\u0451\u043D\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443.",
              "\u0415\u0441\u043B\u0438 \u0442\u044B \u043E\u0448\u0438\u0431\u0451\u0448\u044C\u0441\u044F, \u043F\u0440\u043E\u0437\u0432\u0443\u0447\u0438\u0442 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u043D\u044B\u0439 \u0441\u0438\u0433\u043D\u0430\u043B \u0438 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435, \u043D\u043E \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u0441\u044F.\n\u041C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0433\u043E\u0442\u043E\u0432\u044B\u0439 \u0442\u0435\u043A\u0441\u0442 \u0438\u0437 \u0441\u043F\u0438\u0441\u043A\u0430 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430, \u0438\u043C\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0441\u0432\u043E\u0439 \u0444\u0430\u0439\u043B \u0438\u043B\u0438 \u0432\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043B\u044E\u0431\u043E\u0439 \u0442\u0435\u043A\u0441\u0442.\n\u041F\u043E\u0441\u043B\u0435 \u0432\u044B\u0431\u043E\u0440\u0430 \u0442\u0435\u043A\u0441\u0442\u0430 \u0432 \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u043F\u043E\u044F\u0432\u044F\u0442\u0441\u044F \u0435\u0433\u043E \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432 \u0441 \u0443\u0447\u0451\u0442\u043E\u043C \u043F\u0440\u043E\u0431\u0435\u043B\u043E\u0432. \u042D\u0442\u0438 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u0442\u0430\u043A\u0436\u0435 \u0432\u0438\u0434\u043D\u044B \u0432 \u0432\u0438\u0434\u0436\u0435\u0442\u0435 \u0441\u0442\u043E\u043B\u0430, \u0447\u0442\u043E\u0431\u044B \u0434\u0440\u0443\u0433\u0438\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u043C\u043E\u0433\u043B\u0438 \u043E\u0446\u0435\u043D\u0438\u0442\u044C \u0434\u043B\u0438\u043D\u0443 \u043F\u0430\u0440\u0442\u0438\u0438 \u0434\u043E \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u044F.",
              "\u0415\u0441\u043B\u0438 \u0445\u043E\u0447\u0435\u0448\u044C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0441\u0432\u043E\u0439 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B, \u0432\u044B\u0431\u0435\u0440\u0438 \u00AB\u0412\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0442\u0435\u043A\u0441\u0442\u00BB. \u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0432\u0432\u0435\u0434\u0438 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435, \u0437\u0430\u0442\u0435\u043C \u043D\u0430\u0436\u043C\u0438 Tab, \u0447\u0442\u043E\u0431\u044B \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u043F\u043E\u043B\u0435 \u0442\u0435\u043A\u0441\u0442\u0430.",
              "\u0418\u043C\u043F\u043E\u0440\u0442\u0438\u0440\u0443\u0435\u043C\u044B\u0435 \u0444\u0430\u0439\u043B\u044B \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u0442\u044C \u0432 \u043A\u043E\u0434\u0438\u0440\u043E\u0432\u043A\u0435 UTF-8. \u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439 \u0440\u0430\u0437\u043C\u0435\u0440 \u0444\u0430\u0439\u043B\u0430 \u0438\u043B\u0438 \u0432\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430 - 1000 \u043A\u0411. \u041F\u043E\u0441\u043A\u043E\u043B\u044C\u043A\u0443 \u043D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0441\u0438\u043C\u0432\u043E\u043B\u044B \u0437\u0430\u043D\u0438\u043C\u0430\u044E\u0442 \u0431\u043E\u043B\u044C\u0448\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0431\u0430\u0439\u0442\u0430, \u044D\u0442\u043E \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u043C\u0435\u043D\u044C\u0448\u0435 \u043C\u0438\u043B\u043B\u0438\u043E\u043D\u0430 \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432. \u0422\u0432\u043E\u0438 \u0442\u0435\u043A\u0441\u0442\u044B \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E \u043D\u0430 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435. \u041E\u0434\u043D\u0430\u043A\u043E \u0435\u0441\u043B\u0438 \u0442\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0448\u044C \u0441\u0432\u043E\u0439 \u0442\u0435\u043A\u0441\u0442 \u0432 \u043C\u043D\u043E\u0433\u043E\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0439 \u0438\u0433\u0440\u0435, \u043F\u0440\u0438 \u0435\u0451 \u043D\u0430\u0447\u0430\u043B\u0435 \u043E\u043D \u0431\u0443\u0434\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430\u043C \u0447\u0435\u0440\u0435\u0437 \u0441\u0435\u0440\u0432\u0435\u0440 Elten.\n\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 \u0434\u043B\u0438\u0442\u0441\u044F \u0434\u043E \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u0432\u0441\u0435\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430. \u0415\u0441\u043B\u0438 \u0445\u043E\u0447\u0435\u0448\u044C \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0431\u044B\u0441\u0442\u0440\u0435\u0435, \u043C\u043E\u0436\u043D\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438. \u041F\u043E \u0435\u0433\u043E \u0438\u0441\u0442\u0435\u0447\u0435\u043D\u0438\u0438 \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0442\u044B \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0441\u044F \u043F\u043E\u0441\u0440\u0435\u0434\u0438 \u0441\u043B\u043E\u0432\u0430.\n\u041F\u0440\u0438 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u043C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043D\u0430\u0431\u043E\u0440 \u0431\u0435\u0437 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430. \u0412 \u044D\u0442\u043E\u043C \u0441\u043B\u0443\u0447\u0430\u0435 \u0442\u044B \u043F\u0438\u0448\u0435\u0448\u044C \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442, \u0430 \u043D\u0435 \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u0435\u0448\u044C \u0433\u043E\u0442\u043E\u0432\u044B\u0439. \u0415\u0441\u043B\u0438 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0442\u044C \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438, \u043C\u043E\u0436\u043D\u043E \u043F\u0438\u0441\u0430\u0442\u044C \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0443\u0433\u043E\u0434\u043D\u043E. \u0414\u043B\u044F \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0442\u0430\u043A\u043E\u0439 \u0441\u0435\u0441\u0441\u0438\u0438 \u0432\u044B\u0431\u0435\u0440\u0438 \u00AB\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u043D\u0430\u0431\u043E\u0440\u00BB.\n\u041F\u0440\u0438 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E\u043C \u043F\u0435\u0440\u0435\u043F\u0435\u0447\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u0438 \u0433\u043E\u0442\u043E\u0432\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430 \u0438\u0433\u0440\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0442\u0432\u043E\u0439 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E \u043F\u0440\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0438 \u0438\u043B\u0438 \u0432\u044B\u0445\u043E\u0434\u0435. \u041F\u043E\u0437\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0441 \u0442\u043E\u0433\u043E \u0436\u0435 \u043C\u0435\u0441\u0442\u0430, \u0430 \u043D\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C \u0442\u0435\u043A\u0441\u0442 \u0437\u0430\u043D\u043E\u0432\u043E. \u0415\u0441\u043B\u0438 \u0445\u043E\u0447\u0435\u0448\u044C \u043F\u0440\u043E\u0439\u0442\u0438 \u0432\u0435\u0441\u044C \u0442\u0435\u043A\u0441\u0442 \u0435\u0449\u0451 \u0440\u0430\u0437, \u0441\u0431\u0440\u043E\u0441\u044C \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \u00AB\u041B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0435 \u0442\u0435\u043A\u0441\u0442\u044B \u0438 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u00BB."),
            rule_section(:main_7, "\u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430",
              "\u0412 \u044D\u0442\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0438\u0433\u0440\u0430 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430. \u0422\u0432\u043E\u044F \u0437\u0430\u0434\u0430\u0447\u0430 - \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0436\u0434\u043E\u0435 \u0438\u0437 \u043D\u0438\u0445 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C.",
              "\u0412 \u043E\u0442\u043B\u0438\u0447\u0438\u0435 \u043E\u0442 \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0433\u043E \u043D\u0430\u0431\u043E\u0440\u0430, \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0432\u0432\u043E\u0434\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u0438\u043C\u0432\u043E\u043B\u0430. \u0415\u0441\u043B\u0438 \u043D\u0430\u0436\u043C\u0451\u0448\u044C \u043D\u0435\u0432\u0435\u0440\u043D\u0443\u044E \u043A\u043B\u0430\u0432\u0438\u0448\u0443, \u043F\u043E\u043B\u0443\u0447\u0438\u0448\u044C \u043E\u0434\u043D\u0443 \u043E\u0448\u0438\u0431\u043A\u0443, \u043D\u043E \u043A\u0443\u0440\u0441\u043E\u0440 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u043D\u0430 \u043C\u0435\u0441\u0442\u0435. \u0427\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C, \u043D\u0443\u0436\u043D\u043E \u0432\u0432\u0435\u0441\u0442\u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u0441\u0438\u043C\u0432\u043E\u043B.",
              "Backspace \u043D\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442, \u043F\u043E\u0441\u043A\u043E\u043B\u044C\u043A\u0443 \u043D\u0435\u0432\u0435\u0440\u043D\u044B\u0435 \u0441\u0438\u043C\u0432\u043E\u043B\u044B \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043A \u0443\u0436\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u043E\u043C\u0443 \u043D\u0430\u0447\u0430\u043B\u0443 \u0441\u043B\u043E\u0432\u0430.",
              "\u0412 \u043C\u043D\u043E\u0433\u043E\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0439 \u0438\u0433\u0440\u0435 \u0442\u0430\u043A\u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0431\u0435\u0437\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0432 \u043F\u044F\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434.\n\u0415\u0441\u043B\u0438 \u0437\u0430 \u044D\u0442\u043E \u0432\u0440\u0435\u043C\u044F \u043D\u0435 \u043D\u0430\u0447\u0430\u0442\u044C \u0438\u043B\u0438 \u043D\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u043D\u0430\u0431\u043E\u0440, \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u043D\u0430 \u043E\u0448\u0438\u0431\u043A\u0430. \u0422\u0430\u0439\u043C\u0435\u0440 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0438 \u0434\u043E \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u043F\u0435\u0440\u0432\u043E\u0439 \u043A\u043B\u0430\u0432\u0438\u0448\u0438.",
              "\u0421 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043A\u043B\u0430\u0432\u0438\u0448 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0441\u043B\u043E\u0432\u043E \u0438\u043B\u0438 \u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u043F\u0440\u043E\u0438\u0437\u043D\u0435\u0441\u0442\u0438 \u0435\u0433\u043E \u043F\u043E \u0431\u0443\u043A\u0432\u0430\u043C. \u041F\u043E\u043A\u0430 \u0433\u043E\u0432\u043E\u0440\u0438\u0442 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u0430 \u044D\u043A\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u0430, \u0442\u0430\u0439\u043C\u0435\u0440 \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u0430 \u043F\u043E\u0441\u043B\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u044F \u0441\u043D\u043E\u0432\u0430 \u0434\u0430\u0451\u0442\u0441\u044F \u043F\u043E\u043B\u043D\u044B\u0445 \u043F\u044F\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434.",
              "\u041F\u0440\u0438 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u0448\u0442\u0440\u0430\u0444\u0430 \u0437\u0430 \u0431\u0435\u0437\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043D\u0435\u0442, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u0432 \u0441\u0432\u043E\u0451\u043C \u0442\u0435\u043C\u043F\u0435.\n\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u044D\u0442\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0431\u044B\u0447\u043D\u0443\u044E \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0443, \u0432\u0432\u043E\u0434 \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E \u0438\u043B\u0438 \u0441\u043C\u0435\u0448\u0430\u043D\u043D\u044B\u0439 \u0440\u0435\u0436\u0438\u043C.",
              "\u0412 \u0441\u043C\u0435\u0448\u0430\u043D\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0441\u043F\u043E\u0441\u043E\u0431 \u0432\u0432\u043E\u0434\u0430 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E.",
              "\u041F\u043E\u0434\u0440\u043E\u0431\u043D\u0435\u0435 \u043E \u0432\u0432\u043E\u0434\u0435 \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E \u0447\u0438\u0442\u0430\u0439 \u0434\u0430\u043B\u0435\u0435 \u0432 \u044D\u0442\u043E\u043C \u0440\u0430\u0437\u0434\u0435\u043B\u0435."),
            rule_section(:main_9, "\u0426\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0430\u043C\u044F\u0442\u0438",
              "\u042D\u0442\u043E\u0442 \u0440\u0435\u0436\u0438\u043C \u043F\u043E\u0441\u0432\u044F\u0449\u0451\u043D \u0437\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u044E \u0432\u0441\u0451 \u0431\u043E\u043B\u0435\u0435 \u0434\u043B\u0438\u043D\u043D\u043E\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0441\u043B\u043E\u0432.",
              "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0438\u0437\u043D\u043E\u0441\u0438\u0442 \u043E\u0434\u043D\u043E \u0441\u043B\u043E\u0432\u043E, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C. \u0417\u0430\u0442\u0435\u043C \u043E\u043D\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435, \u043D\u043E \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E.",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0437 \u043D\u0443\u0436\u043D\u043E \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u044C \u0432\u0441\u044E \u0446\u0435\u043F\u043E\u0447\u043A\u0443 \u0441 \u0441\u0430\u043C\u043E\u0433\u043E \u043D\u0430\u0447\u0430\u043B\u0430, \u0440\u0430\u0437\u0434\u0435\u043B\u044F\u044F \u0441\u043B\u043E\u0432\u0430 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0435\u0441\u043B\u0438 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0442\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0448\u044C \u00AB\u043A\u043E\u0442\u00BB, \u0430 \u0437\u0430\u0442\u0435\u043C \u00AB\u0441\u0430\u0434\u00BB, \u043D\u0443\u0436\u043D\u043E \u0432\u0432\u0435\u0441\u0442\u0438 \u043E\u0431\u0430 \u0441\u043B\u043E\u0432\u0430 \u0432 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u043C \u043F\u043E\u0440\u044F\u0434\u043A\u0435. \u041A\u043E\u0433\u0434\u0430 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0442\u0440\u0435\u0442\u044C\u0435 \u0441\u043B\u043E\u0432\u043E, \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u0432\u0441\u0435 \u0442\u0440\u0438.",
              "\u0421 \u043A\u0430\u0436\u0434\u043E\u0439 \u043F\u043E\u043F\u044B\u0442\u043A\u043E\u0439 \u0437\u0430\u0434\u0430\u0447\u0430 \u0443\u0441\u043B\u043E\u0436\u043D\u044F\u0435\u0442\u0441\u044F, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u043D\u0443\u0436\u043D\u043E \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044C \u0432 \u043F\u0430\u043C\u044F\u0442\u0438 \u0432\u0441\u0451 \u0431\u043E\u043B\u044C\u0448\u0435 \u0441\u043B\u043E\u0432.",
              "\u041A\u0430\u043A \u0438 \u0432 \u0440\u0435\u0436\u0438\u043C\u0435 \u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430, \u043D\u0435\u0432\u0435\u0440\u043D\u044B\u0439 \u0441\u0438\u043C\u0432\u043E\u043B \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u043E\u0448\u0438\u0431\u043A\u0443, \u043D\u043E \u043D\u0435 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043A\u0443\u0440\u0441\u043E\u0440, \u0430 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C Backspace \u043D\u0435\u043B\u044C\u0437\u044F. \u0417\u0434\u0435\u0441\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0442\u0430\u043A\u0438\u0435 \u0436\u0435 \u0448\u0442\u0440\u0430\u0444\u044B \u0437\u0430 \u0431\u0435\u0437\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0432\u0432\u043E\u0434 \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E.",
              "\u0421\u043C\u0435\u0448\u0430\u043D\u043D\u044B\u0439 \u0440\u0435\u0436\u0438\u043C \u0432 \u044D\u0442\u043E\u043C \u0441\u043B\u0443\u0447\u0430\u0435 \u2014 \u0434\u043B\u044F \u043D\u0435\u0438\u0441\u043F\u0440\u0430\u0432\u0438\u043C\u044B\u0445 \u043D\u0435\u0440\u0434\u043E\u0432, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u043D\u0443\u0436\u043D\u043E \u0432\u0441\u043F\u043E\u043C\u043D\u0438\u0442\u044C \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043B\u043E\u0432\u043E, \u043D\u043E \u0438 \u0441\u043F\u043E\u0441\u043E\u0431, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0435\u0433\u043E \u0441\u043B\u0435\u0434\u043E\u0432\u0430\u043B\u043E \u0432\u0432\u0435\u0441\u0442\u0438."),
            rule_section(:main_10, "\u0420\u0435\u0436\u0438\u043C \u0432\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u044F",
              "\u0412 \u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0438 \u043D\u0443\u0436\u043D\u043E \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u043E\u0447\u0435\u0440\u0435\u0434\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u0434\u043E \u0442\u043E\u0433\u043E, \u043A\u0430\u043A \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u043C\u0443\u0437\u044B\u043A\u0430.",
              "\u0414\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430 \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043E \u0441\u0432\u043E\u0451 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438, \u0437\u0430\u0432\u0438\u0441\u044F\u0449\u0435\u0435 \u043E\u0442 \u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0437\u0430\u043F\u0438\u0441\u0438.",
              "\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0434\u0438\u043D \u0438\u0437 \u0442\u0440\u0451\u0445 \u0443\u0440\u043E\u0432\u043D\u0435\u0439 \u0441\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u0438.",
              "- \u041B\u0451\u0433\u043A\u0438\u0439 - \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E 16 \u0441\u0435\u043A\u0443\u043D\u0434.\n- \u0421\u0440\u0435\u0434\u043D\u0438\u0439 - \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E 10,67 \u0441\u0435\u043A\u0443\u043D\u0434\u044B.\n- \u0421\u043B\u043E\u0436\u043D\u044B\u0439 - \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E 6,64 \u0441\u0435\u043A\u0443\u043D\u0434\u044B.",
              "\u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430 \u043C\u0443\u0437\u044B\u043A\u0430 \u0443\u0441\u043A\u043E\u0440\u044F\u0435\u0442\u0441\u044F \u043D\u0430 2,5 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u0430, \u0430 \u0435\u0451 \u0442\u043E\u043D \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442\u0441\u044F.",
              "\u042D\u0442\u043E \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u0447\u0435\u043C \u0434\u043E\u043B\u044C\u0448\u0435 \u0442\u044B \u0438\u0433\u0440\u0430\u0435\u0448\u044C \u0431\u0435\u0437 \u043E\u0448\u0438\u0431\u043E\u043A, \u0442\u0435\u043C \u043C\u0435\u043D\u044C\u0448\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043D\u0430 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0441\u043B\u043E\u0432\u0430.\n\u0412 \u044D\u0442\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u043D\u0435 \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0442\u044C \u0441\u043B\u043E\u0432\u0430 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. \u041A\u0430\u043A \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u0441\u0438\u043C\u0432\u043E\u043B, \u0438\u0433\u0440\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0441\u043B\u043E\u0432\u0443.",
              "\u0415\u0441\u043B\u0438 \u043D\u0430\u0436\u0430\u0442\u044C \u043D\u0435\u0432\u0435\u0440\u043D\u0443\u044E \u043A\u043B\u0430\u0432\u0438\u0448\u0443, \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u043D\u0430 \u043E\u0448\u0438\u0431\u043A\u0430, \u043D\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u043D\u0430\u0447\u0430\u043B\u043E \u0441\u043B\u043E\u0432\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F.",
              "\u0415\u0441\u043B\u0438 \u043C\u0443\u0437\u044B\u043A\u0430 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u0434\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0441\u043B\u043E\u0432\u0430, \u0438\u0433\u0440\u0430 \u0434\u043E\u0431\u0430\u0432\u0438\u0442 \u043E\u0448\u0438\u0431\u043A\u0443 \u0438 \u043D\u0430\u0447\u043D\u0451\u0442 \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E. \u0412 \u044D\u0442\u043E\u043C \u0441\u043B\u0443\u0447\u0430\u0435 \u043C\u0443\u0437\u044B\u043A\u0430 \u043D\u0435 \u0443\u0441\u043A\u043E\u0440\u0438\u0442\u0441\u044F.\n\u041F\u043E\u043C\u043D\u0438, \u0447\u0442\u043E \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u0447\u0442\u0435\u043D\u0438\u0435 \u0441\u043B\u043E\u0432\u0430, \u043F\u0440\u043E\u0438\u0437\u043D\u0435\u0441\u0435\u043D\u0438\u0435 \u043F\u043E \u0431\u0443\u043A\u0432\u0430\u043C \u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u0437\u0432\u0443\u043A\u0430 \u043C\u0443\u0437\u044B\u043A\u0438 \u043D\u0435 \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0442 \u043E\u0442\u0441\u0447\u0451\u0442 \u0432\u0440\u0435\u043C\u0435\u043D\u0438.",
              "\u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0442\u0430\u0439\u043C\u0435\u0440\u0430 \u0431\u0435\u0437\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442, \u043F\u043E\u0441\u043A\u043E\u043B\u044C\u043A\u0443 \u0432\u0440\u0435\u043C\u044F \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043E \u0441\u0430\u043C\u043E\u0439 \u043C\u0443\u0437\u044B\u043A\u043E\u0439.",
              "\u0417\u0434\u0435\u0441\u044C \u0442\u0430\u043A\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u043E\u0439, \u0432\u0432\u043E\u0434\u043E\u043C \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E \u0438\u043B\u0438 \u0441\u043C\u0435\u0448\u0430\u043D\u043D\u044B\u043C \u0440\u0435\u0436\u0438\u043C\u043E\u043C."),
            rule_section(:main_11, "\u0412\u0432\u043E\u0434 \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u0432\u0432\u043E\u0434\u0430 \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u043A\u043B\u0430\u0432\u0438\u0448\u0430\u043C\u0438 \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0443, \u0438\u043C\u0438\u0442\u0438\u0440\u0443\u044E\u0449\u0443\u044E \u0431\u0440\u0430\u0439\u043B\u0435\u0432\u0441\u043A\u0443\u044E \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0443.",
              "\u0422\u043E\u0447\u043A\u0430\u043C \u0411\u0440\u0430\u0439\u043B\u044F \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438.",
              "- \u0422\u043E\u0447\u043A\u0438 1, 2 \u0438 3 - F, D, S.\n- \u0422\u043E\u0447\u043A\u0438 4, 5 \u0438 6 - J, K, L.\n- \u0422\u043E\u0447\u043A\u0430 7 - A.\n- \u0422\u043E\u0447\u043A\u0430 8 - \u0442\u043E\u0447\u043A\u0430 \u0441 \u0437\u0430\u043F\u044F\u0442\u043E\u0439.",
              "\u0427\u0442\u043E\u0431\u044B \u0432\u0432\u0435\u0441\u0442\u0438 \u0441\u0438\u043C\u0432\u043E\u043B \u0411\u0440\u0430\u0439\u043B\u044F, \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u043D\u0430\u0436\u043C\u0438 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438, \u0430 \u0437\u0430\u0442\u0435\u043C \u043E\u0442\u043F\u0443\u0441\u0442\u0438 \u0438\u0445.\n\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u0438 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0440\u0430\u0437\u043D\u044B\u0435 \u0442\u0430\u0431\u043B\u0438\u0446\u044B \u0411\u0440\u0430\u0439\u043B\u044F \u0434\u043B\u044F \u0441\u0432\u043E\u0435\u0433\u043E \u044F\u0437\u044B\u043A\u0430 \u0438\u043B\u0438 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0443\u044E \u0442\u0430\u0431\u043B\u0438\u0446\u0443 Liblouis \u0432 \u0432\u0438\u0434\u0435 \u0444\u0430\u0439\u043B\u0430 ctb, utb, tbl \u043B\u0438\u0431\u043E uti."),
            rule_section(:main_12, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u0438",
              "\u041D\u0430\u0436\u043C\u0438 Ctrl+P, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u041A\u043B\u0430\u0432\u043E\u043C\u0430\u043D\u0438\u0438.",
              "\u0417\u0434\u0435\u0441\u044C \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B \u0432\u0432\u043E\u0434\u0430 \u043F\u043E \u0411\u0440\u0430\u0439\u043B\u044E, \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u044F \u043D\u0430\u0431\u043E\u0440\u0430, \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0439 \u043E\u0431 \u043E\u0448\u0438\u0431\u043A\u0430\u0445 \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u0438 \u043C\u0443\u0437\u044B\u043A\u0438.",
              "\u041E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u0435 \u043D\u0430\u0431\u043E\u0440\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442, \u0447\u0442\u043E \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0438\u0437\u043D\u043E\u0441\u0438\u0442 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u0432\u043E\u0434\u0430 \u0442\u0435\u043A\u0441\u0442\u0430.",
              "\u041C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Elten \u0438\u043B\u0438 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0447\u0442\u0435\u043D\u0438\u0435 \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432, \u0441\u043B\u043E\u0432, \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432 \u0438 \u0441\u043B\u043E\u0432 \u0432\u043C\u0435\u0441\u0442\u0435 \u043B\u0438\u0431\u043E \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u0435.",
              "\u042D\u0442\u0438 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u0438\u0433\u0440\u043E\u0432\u043E\u043C \u043F\u043E\u043B\u0435 \u0432\u0432\u043E\u0434\u0430.\n\u0415\u0449\u0451 \u043E\u0434\u0438\u043D \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442, \u043A\u0430\u043A \u0438\u0433\u0440\u0430 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0442\u0435\u0431\u0435 \u043E \u0434\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u044B\u0445 \u043E\u0448\u0438\u0431\u043A\u0430\u0445.",
              "\u0420\u0435\u0447\u0435\u0432\u044B\u0435 \u0438 \u0437\u0432\u0443\u043A\u043E\u0432\u044B\u0435 \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u044F \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E. \u041C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043E\u0431\u0430 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430, \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0434\u0438\u043D \u0438\u0437 \u043D\u0438\u0445 \u0438\u043B\u0438 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u044F.\n\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440 - \u043F\u043E\u043B\u0437\u0443\u043D\u043E\u043A \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u0438 \u043C\u0443\u0437\u044B\u043A\u0438 \u043E\u0442 0 \u0434\u043E 100 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u043E\u0432."),
            rule_section(:main_13, "\u0420\u0430\u0443\u043D\u0434\u044B \u0438 \u043C\u043D\u043E\u0433\u043E\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0435 \u043C\u0430\u0442\u0447\u0438",
              "\u0412 \u0440\u0435\u0436\u0438\u043C\u0430\u0445 \u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430, \u0426\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0430\u043C\u044F\u0442\u0438 \u0438 \u0412\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u0438\u043B\u0438 \u043C\u0430\u0442\u0447, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F \u0434\u043E \u0442\u0435\u0445 \u043F\u043E\u0440, \u043F\u043E\u043A\u0430 \u0432\u0435\u0434\u0443\u0449\u0438\u0439 \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442 \u0435\u0433\u043E.",
              "\u0412 \u043A\u0430\u0436\u0434\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043E\u0447\u043A\u0438 \u043F\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0430.",
              "\u0415\u0441\u043B\u0438 \u0442\u044B \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u043C\u0430\u0442\u0447 \u0438\u0437 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432, \u0438\u0442\u043E\u0433\u043E\u0432\u043E\u0433\u043E \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432.",
              "\u0422\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u0443\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0438 \u043A\u043E\u0440\u043E\u0442\u043A\u0443\u044E \u0438\u0433\u0440\u0443, \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0442\u0443\u0440\u043D\u0438\u0440, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043E\u0434\u043D\u0430 \u043D\u0435\u0443\u0434\u0430\u0447\u0430 \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0440\u0435\u0448\u0430\u0435\u0442 \u0438\u0441\u0445\u043E\u0434 \u0432\u0441\u0435\u0433\u043E \u0441\u043E\u0440\u0435\u0432\u043D\u043E\u0432\u0430\u043D\u0438\u044F."),
            rule_section(:touch_0, "\u0421\u043B\u0435\u043F\u0430\u044F \u043F\u0435\u0447\u0430\u0442\u044C",
              "\u0421\u043B\u0435\u043F\u0430\u044F \u043F\u0435\u0447\u0430\u0442\u044C - \u044D\u0442\u043E \u043C\u0435\u0442\u043E\u0434 \u043D\u0430\u0431\u043E\u0440\u0430 \u0442\u0435\u043A\u0441\u0442\u0430 \u0431\u0435\u0437 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043D\u0430 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0443. \u0411\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u0440\u0435\u0433\u0443\u043B\u044F\u0440\u043D\u044B\u043C \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043A\u0430\u043C \u0442\u044B \u043D\u0430\u0443\u0447\u0438\u0448\u044C\u0441\u044F \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u044C \u043D\u0443\u0436\u043D\u044B\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438, \u0447\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C, \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C \u0438 \u043A\u043E\u043C\u0444\u043E\u0440\u0442 \u043F\u0435\u0447\u0430\u0442\u0438. \u042D\u0442\u043E\u043C\u0443 \u043C\u0435\u0442\u043E\u0434\u0443 \u043E\u0431\u0443\u0447\u0430\u044E\u0442\u0441\u044F \u043B\u044E\u0434\u0438 \u0441\u0430\u043C\u044B\u0445 \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0440\u043E\u0444\u0435\u0441\u0441\u0438\u0439, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u043D\u0430\u0431\u043E\u0440\u0430 \u0442\u0435\u043A\u0441\u0442\u0430 \u043D\u0430\u043F\u0440\u044F\u043C\u0443\u044E \u0432\u043B\u0438\u044F\u0435\u0442 \u043D\u0430 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0442\u0440\u0443\u0434\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u0438\u0441\u0442\u044B, \u0436\u0443\u0440\u043D\u0430\u043B\u0438\u0441\u0442\u044B \u0438 \u043F\u0438\u0441\u0430\u0442\u0435\u043B\u0438."),
            rule_section(:touch_1, "\u041E\u0441\u043D\u043E\u0432\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430",
              "\u041F\u043E\u043B\u043E\u0436\u0438 \u043F\u0430\u043B\u044C\u0446\u044B \u043B\u0435\u0432\u043E\u0439 \u0440\u0443\u043A\u0438 \u043D\u0430 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0424, \u042B, \u0412, \u0410, \u0430 \u043F\u0440\u0430\u0432\u043E\u0439 - \u043D\u0430 \u041E, \u041B, \u0414, \u0416. \u0411\u043E\u043B\u044C\u0448\u0438\u0435 \u043F\u0430\u043B\u044C\u0446\u044B \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0438 \u043D\u0430 \u043F\u0440\u043E\u0431\u0435\u043B\u0435.",
              "\u041D\u0430 \u043A\u043B\u0430\u0432\u0438\u0448\u0430\u0445 \u0410 \u0438 \u041E \u0435\u0441\u0442\u044C \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u0438\u0435 \u0442\u0430\u043A\u0442\u0438\u043B\u044C\u043D\u044B\u0435 \u0432\u044B\u0441\u0442\u0443\u043F\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u044C \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043E\u0431\u0435\u0438\u0445 \u0440\u0443\u043A, \u043D\u0435 \u0433\u043B\u044F\u0434\u044F \u043D\u0430 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0443.",
              "\u042D\u0442\u043E \u043E\u0441\u043D\u043E\u0432\u043D\u0430\u044F \u043F\u043E\u0437\u0438\u0446\u0438\u044F, \u0438\u0437 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0431\u0438\u0440\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u0438\u043C\u0432\u043E\u043B\u044B, \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u044F \u043F\u0430\u043B\u044C\u0446\u044B \u043D\u0430 \u0441\u043E\u0441\u0435\u0434\u043D\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u043F\u0435\u0447\u0430\u0442\u0430\u0442\u044C \u0431\u0443\u043A\u0432\u0443 \u044F, \u043F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438 \u043C\u0438\u0437\u0438\u043D\u0435\u0446 \u043B\u0435\u0432\u043E\u0439 \u0440\u0443\u043A\u0438 \u0432\u043D\u0438\u0437 \u043E\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0444. \u0427\u0442\u043E\u0431\u044B \u043D\u0430\u043F\u0435\u0447\u0430\u0442\u0430\u0442\u044C \u0439, \u043F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438 \u0442\u043E\u0442 \u0436\u0435 \u043F\u0430\u043B\u0435\u0446 \u0432\u0432\u0435\u0440\u0445. \u0414\u043B\u044F \u0431\u0443\u043A\u0432\u044B \u043D \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u043F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438\u0442\u044C \u0443\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u0430\u043B\u0435\u0446 \u043F\u0440\u0430\u0432\u043E\u0439 \u0440\u0443\u043A\u0438 \u043E\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u043E \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043B\u0435\u0432\u043E."),
            rule_section(:touch_2, "\u041F\u044F\u0442\u044C \u0437\u043E\u043B\u043E\u0442\u044B\u0445 \u043F\u0440\u0430\u0432\u0438\u043B \u0441\u043B\u0435\u043F\u043E\u0439 \u043F\u0435\u0447\u0430\u0442\u0438",
              "1. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439 \u0432\u0441\u0435 \u043F\u0430\u043B\u044C\u0446\u044B. \u0417\u0430 \u043A\u0430\u0436\u0434\u044B\u043C \u043F\u0430\u043B\u044C\u0446\u0435\u043C \u0437\u0430\u043A\u0440\u0435\u043F\u043B\u0435\u043D\u044B \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438. \u0412\u043E \u0432\u0440\u0435\u043C\u044F \u043E\u0431\u0443\u0447\u0435\u043D\u0438\u044F \u0441\u0442\u0430\u0440\u0430\u0439\u0441\u044F \u0441\u043E\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u044D\u0442\u043E \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435.",
              "2. \u0412\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0439\u0441\u044F \u0432 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435. \u041F\u043E\u0441\u043B\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0439 \u043F\u0430\u043B\u0435\u0446 \u043D\u0430 \u0435\u0433\u043E \u043E\u0441\u043D\u043E\u0432\u043D\u0443\u044E \u043F\u043E\u0437\u0438\u0446\u0438\u044E. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0441\u043B\u0435 \u0432\u0432\u043E\u0434\u0430 \u0431\u0443\u043A\u0432\u044B \u043A \u0432\u0435\u0440\u043D\u0438 \u0443\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u0430\u043B\u0435\u0446 \u043B\u0435\u0432\u043E\u0439 \u0440\u0443\u043A\u0438 \u043D\u0430 \u043A\u043B\u0430\u0432\u0438\u0448\u0443 \u0430.",
              "3. \u041D\u0430\u0436\u0438\u043C\u0430\u0439 \u043F\u0440\u043E\u0431\u0435\u043B \u0431\u043E\u043B\u044C\u0448\u0438\u043C \u043F\u0430\u043B\u044C\u0446\u0435\u043C. \u0414\u043B\u044F \u0437\u0430\u0433\u043B\u0430\u0432\u043D\u044B\u0445 \u0431\u0443\u043A\u0432 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439 Shift \u043D\u0430 \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u043B\u043E\u0436\u043D\u043E\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u0435 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044B. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0434\u043B\u044F \u0437\u0430\u0433\u043B\u0430\u0432\u043D\u043E\u0439 \u0424 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439 \u043F\u0440\u0430\u0432\u044B\u0439 Shift, \u0430 \u0434\u043B\u044F \u0437\u0430\u0433\u043B\u0430\u0432\u043D\u043E\u0439 \u041B - \u043B\u0435\u0432\u044B\u0439.",
              "4. \u041D\u0435 \u043D\u0430\u043F\u0440\u044F\u0433\u0430\u0439 \u0440\u0443\u043A\u0438. \u0412\u044B\u043F\u043E\u043B\u043D\u044F\u0439 \u043B\u0451\u0433\u043A\u0438\u0435, \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0438 \u0441\u0442\u0430\u0440\u0430\u0439\u0441\u044F \u0434\u0435\u0440\u0436\u0430\u0442\u044C \u0437\u0430\u043F\u044F\u0441\u0442\u044C\u044F \u0432 \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u043C, \u043F\u043E \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043F\u0440\u044F\u043C\u043E\u043C \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0438.",
              "5. \u041D\u0435 \u0442\u043E\u0440\u043E\u043F\u0438\u0441\u044C. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0430\u0443\u0447\u0438\u0441\u044C \u043F\u0435\u0447\u0430\u0442\u0430\u0442\u044C \u0442\u043E\u0447\u043D\u043E, \u0430 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u043F\u0440\u0438\u0434\u0451\u0442 \u0441 \u043F\u0440\u0430\u043A\u0442\u0438\u043A\u043E\u0439."),
            rule_section(:touch_3, "\u041A\u0430\u043A \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u044D\u0444\u0444\u0435\u043A\u0442\u0438\u0432\u043D\u043E?",
              "\u0422\u0440\u0435\u043D\u0438\u0440\u0443\u0439\u0441\u044F \u0440\u0435\u0433\u0443\u043B\u044F\u0440\u043D\u043E. \u0414\u043B\u044F \u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u0437\u0430\u043D\u044F\u0442\u0438\u044F \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u043A\u043E\u043B\u043E 10-15 \u043C\u0438\u043D\u0443\u0442.",
              "\u0423\u0434\u0435\u043B\u044F\u0439 \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u0438. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0442\u0430\u0440\u0430\u0439\u0441\u044F \u0441\u0432\u0435\u0441\u0442\u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043E\u0448\u0438\u0431\u043E\u043A \u0432 \u0442\u0435\u043A\u0441\u0442\u0435 \u043A \u043C\u0438\u043D\u0438\u043C\u0443\u043C\u0443 \u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0442\u043E\u043C \u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u043E \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0439 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u043D\u0430\u0431\u043E\u0440\u0430.",
              "\u041F\u043E\u0432\u0442\u043E\u0440\u044F\u0439 \u0441\u043B\u043E\u0436\u043D\u044B\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F. \u0415\u0441\u043B\u0438 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u0430\u044F \u043A\u043B\u0430\u0432\u0438\u0448\u0430 \u0438\u043B\u0438 \u0441\u043B\u043E\u0432\u043E \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0442 \u0437\u0430\u0442\u0440\u0443\u0434\u043D\u0435\u043D\u0438\u044F, \u0443\u0434\u0435\u043B\u0438 \u0438\u043C \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435.",
              "\u0421\u043B\u0435\u0434\u0438 \u0437\u0430 \u0441\u0432\u043E\u0438\u043C \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u043E\u043C. \u0421\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0440\u0430\u0437\u043D\u044B\u0445 \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043E\u043A, \u043D\u043E \u043F\u043E\u043C\u043D\u0438, \u0447\u0442\u043E \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C - \u043D\u0435 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0432\u0430\u0436\u043D\u044B\u0439 \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C.",
              "\u0414\u0435\u043B\u0430\u0439 \u043F\u0435\u0440\u0435\u0440\u044B\u0432\u044B. \u0415\u0441\u043B\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0448\u044C, \u0447\u0442\u043E \u0442\u0435\u0440\u044F\u0435\u0448\u044C \u043A\u043E\u043D\u0446\u0435\u043D\u0442\u0440\u0430\u0446\u0438\u044E \u0438\u043B\u0438 \u0438\u0441\u043F\u044B\u0442\u044B\u0432\u0430\u0435\u0448\u044C \u0434\u0438\u0441\u043A\u043E\u043C\u0444\u043E\u0440\u0442 \u0432 \u0440\u0443\u043A\u0430\u0445, \u043F\u0440\u0435\u0440\u0432\u0438 \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043A\u0443 \u0438 \u043E\u0442\u0434\u043E\u0445\u043D\u0438."),
            rule_section(:controls, "\u0421\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043A\u043B\u0430\u0432\u0438\u0448",
              "- Ctrl+L: \u041F\u0440\u043E\u0438\u0437\u043D\u0435\u0441\u0442\u0438 \u0442\u0435\u043A\u0443\u0449\u0435\u0435 \u0441\u043B\u043E\u0432\u043E \u043F\u043E \u0431\u0443\u043A\u0432\u0430\u043C.",
              "- Ctrl+O: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0435\u0435 \u0441\u043B\u043E\u0432\u043E.",
              "- Ctrl+;: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0441\u043B\u043E\u0432\u0430 (\u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0432 \u0446\u0435\u043F\u043E\u0447\u043A\u0435 \u043F\u0430\u043C\u044F\u0442\u0438).",
              "- Ctrl+Shift+;: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F (\u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u043F\u0435\u0447\u0430\u0442\u044C).",
              "- Alt+S: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441.",
              "- Ctrl+P: \u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043F\u0435\u0447\u0430\u0442\u0438.",
              "- Space: \u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0441\u043B\u043E\u0432\u043E (\u043A\u0440\u043E\u043C\u0435 \u0432\u044B\u0436\u0438\u0432\u0430\u043D\u0438\u044F).",
              "- Backspace: \u0418\u0441\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0435\u0435 \u0441\u043B\u043E\u0432\u043E (\u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u043F\u0435\u0447\u0430\u0442\u044C).",
              "- Ctrl+S: \u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u0441\u0442\u043E\u043B.",
              "- F1: \u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u043D\u0430\u044F \u0441\u043F\u0440\u0430\u0432\u043A\u0430.",
              "- Ctrl+F1: \u0421\u043F\u0440\u0430\u0432\u043A\u0430 \u0438\u0433\u0440\u044B.",
              "- Escape: \u041F\u043E\u043A\u0438\u043D\u0443\u0442\u044C \u0441\u0442\u043E\u043B.")
          ]
